import { useEffect, useState } from "react";


export default function AgreementTripMap({ tripId, isActive }) {
  const [location, setLocation] = useState(null);
  const [lastUpdated, setLastUpdated] = useState(null);
  const [available, setAvailable] = useState(false);

  useEffect(() => {
    if (!isActive || !tripId) {
      setLocation(null);
      setAvailable(false);
      return undefined;
    }

    let cancelled = false;

    async function fetchLocation() {
      try {
        const response = await fetch(`/api/agreements/trips/${tripId}/live-location`, {
          credentials: "include",
        });
        if (!response.ok) {
          throw new Error("Live location request failed");
        }
        const data = await response.json();
        if (cancelled) {
          return;
        }
        if (data.traccar_available === true) {
          setLocation({
            lat: Number(data.lat),
            lon: Number(data.lon),
            speed: data.speed,
            timestamp: data.timestamp,
          });
          setAvailable(true);
        } else {
          setLocation(null);
          setAvailable(false);
        }
        setLastUpdated(new Date().toLocaleString());
      } catch (error) {
        if (!cancelled) {
          setLocation(null);
          setAvailable(false);
          setLastUpdated(new Date().toLocaleString());
        }
      }
    }

    fetchLocation();
    const intervalId = window.setInterval(fetchLocation, 30000);

    return () => {
      cancelled = true;
      window.clearInterval(intervalId);
    };
  }, [tripId, isActive]);

  if (!isActive) {
    return null;
  }

  if (!available || !location) {
    return (
      <div style={{ color: "var(--color-text-secondary)" }}>
        <p>Live location not available</p>
        <p style={{ fontSize: '12px', marginTop: '4px' }}>GPS tracking will be active once provider is configured.</p>
        {lastUpdated ? <small>Last updated: {lastUpdated}</small> : null}
      </div>
    );
  }

  const { lat, lon } = location;
  const mapUrl = `https://www.openstreetmap.org/export/embed.html?bbox=${lon - 0.01},${lat - 0.01},${lon + 0.01},${lat + 0.01}&layer=mapnik&marker=${lat},${lon}`;

  return (
    <div>
      <iframe
        title="Live truck location"
        src={mapUrl}
        style={{ width: "100%", height: "300px", border: "none", borderRadius: "8px" }}
      />
      {lastUpdated ? (
        <small style={{ color: "var(--color-text-secondary)" }}>Last updated: {lastUpdated}</small>
      ) : null}
    </div>
  );
}

import { useCallback, useEffect, useRef, useState } from 'react'
import { useLocation, useNavigate } from 'react-router-dom'
import { AUTH_STATUSES, useAuthVerification } from '../../auth/AuthVerificationContext'
import {
  AI_API_BASE,
  AI_CHAT_ROUTE,
  DEFAULT_AI_CAPABILITIES,
  appendConversationTurn,
  applyMappedFields,
  buildAssistantContext,
  detectUserRole,
  dispatchTruckUpdate,
  loadAssistantMemory,
  loadAssistantPreferences,
  normalizeMode,
  roleLabel,
  saveAssistantMemory,
  saveAssistantPreferences,
} from '../../lib/aiAssistant'

function isUnavailableAiEndpoint(response) {
  return response?.status === 404 || response?.status === 405
}

export default function GlobalAiAssistant() {
  const location = useLocation()
  const navigate = useNavigate()
  const { status: authStatus, user } = useAuthVerification()
  const verified = authStatus === AUTH_STATUSES.VERIFIED
  const recognitionRef = useRef(null)
  const aiBackendAvailableRef = useRef(null)
  const routePath = `${location.pathname}${location.search}${location.hash}`
  const userRole = user?.role || detectUserRole()
  const [memory, setMemory] = useState(() => loadAssistantMemory(location.pathname, detectUserRole()))
  const [preferences, setPreferences] = useState(() => ({ ...loadAssistantPreferences(), mode: 'minimized' }))
  const [capabilities, setCapabilities] = useState(DEFAULT_AI_CAPABILITIES)
  const [preview, setPreview] = useState('')
  const [questionInput, setQuestionInput] = useState('')
  const [status, setStatus] = useState('Command assistant ready.')
  const [isListening, setIsListening] = useState(false)
  const assistantVisible = normalizeMode(preferences.mode) === 'visible'

  const pageContext = buildAssistantContext({
    pathname: location.pathname,
    userRole,
    memory,
    pageTitle: typeof document !== 'undefined' ? document.title : '',
  })

  const syncRemotePreferences = useCallback(async () => {
    const response = await fetch(`${AI_API_BASE}/preferences`, {
      method: 'POST',
      credentials: 'include',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        languagePreference: 'en',
        visibilityMode: preferences.mode,
        backgroundListening: preferences.backgroundListening,
      }),
    })
    if (isUnavailableAiEndpoint(response)) aiBackendAvailableRef.current = false
    return response
  }, [preferences.backgroundListening, preferences.mode])

  useEffect(() => {
    // eslint-disable-next-line react-hooks/set-state-in-effect
    setMemory(() => loadAssistantMemory(location.pathname, userRole))
  }, [location.pathname, userRole])

  useEffect(() => {
    saveAssistantMemory(memory)
  }, [memory])

  useEffect(() => {
    saveAssistantPreferences(preferences)
    if (!verified || !assistantVisible || aiBackendAvailableRef.current !== true) return
    let active = true
    async function syncPreferences() {
      try {
        if (!active) return
        await syncRemotePreferences()
      } catch {
        // no-op
      }
    }
    syncPreferences()
    return () => {
      active = false
    }
  }, [assistantVisible, preferences, syncRemotePreferences, verified])

  useEffect(() => {
    let active = true

    async function loadCapabilities() {
      if (!verified || !assistantVisible || aiBackendAvailableRef.current === false) return
      try {
        const response = await fetch(`${AI_API_BASE}/capabilities`, {
          method: 'GET',
          credentials: 'include',
        })
        if (isUnavailableAiEndpoint(response)) {
          aiBackendAvailableRef.current = false
          return
        }
        const payload = await response.json()
        if (!active) return
        if (response.ok && payload?.success && payload.capabilities) {
          aiBackendAvailableRef.current = true
          setCapabilities(payload.capabilities)
          await syncRemotePreferences()
        }
      } catch {
        // no-op
      }
    }

    loadCapabilities()
    return () => {
      active = false
    }
  }, [assistantVisible, syncRemotePreferences, user, verified])

  useEffect(() => {
    function handleFocus(event) {
      const target = event.target
      if (!target) return
      setMemory((current) => ({
        ...current,
        activeField: target.id || target.name || null,
        activeForm: target.form?.id || null,
      }))
    }

    document.addEventListener('focusin', handleFocus)
    return () => document.removeEventListener('focusin', handleFocus)
  }, [])

  useEffect(() => {
    function handleHotkey(event) {
      if (event.ctrlKey && event.shiftKey && String(event.key || '').toLowerCase() === 'a') {
        event.preventDefault()
        cycleVisibilityMode()
      }
    }

    document.addEventListener('keydown', handleHotkey)
    return () => document.removeEventListener('keydown', handleHotkey)
  }, [])

  useEffect(() => {
    if (preferences.mode === 'hidden' && preferences.backgroundListening) {
      ensureBackgroundListening()
    }
    if (preferences.mode !== 'hidden' && !preferences.backgroundListening) {
      stopListening()
    }
  }, [preferences.mode, preferences.backgroundListening])

  useEffect(() => {
    return () => stopListening()
  }, [])

  if (location.pathname === AI_CHAT_ROUTE || !verified) {
    return null
  }

  function cycleVisibilityMode() {
    setPreferences((current) => {
      const mode = normalizeMode(current.mode)
      if (mode === 'visible') return { ...current, mode: 'minimized' }
      if (mode === 'minimized') return { ...current, mode: 'hidden' }
      return { ...current, mode: 'visible' }
    })
  }

  function stopListening() {
    try {
      recognitionRef.current?.stop()
    } catch {
      // no-op
    }
    setIsListening(false)
  }

  function ensureRecognition() {
    const Constructor = window.SpeechRecognition || window.webkitSpeechRecognition
    if (!Constructor) return null
    if (recognitionRef.current) return recognitionRef.current

    const recognition = new Constructor()
    recognition.lang = 'en-US'
    recognition.interimResults = false
    recognition.continuous = false
    recognition.maxAlternatives = 1
    recognition.onstart = () => {
      setIsListening(true)
      setStatus('Listening...')
    }
    recognition.onresult = (event) => {
      const transcript = event.results?.[0]?.[0]?.transcript || ''
      handleCapturedTranscript(transcript)
    }
    recognition.onerror = () => {
      setIsListening(false)
      setStatus('Speech recognition unavailable. Type and send request.')
    }
    recognition.onend = () => {
      setIsListening(false)
      if (preferences.mode === 'hidden' && preferences.backgroundListening) {
        ensureBackgroundListening()
      }
    }
    recognitionRef.current = recognition
    return recognition
  }

  function ensureBackgroundListening() {
    const recognition = ensureRecognition()
    if (!recognition || isListening) return
    try {
      recognition.start()
    } catch {
      // no-op
    }
  }

  function handleMicToggle() {
    const recognition = ensureRecognition()
    if (recognition) {
      if (isListening) {
        stopListening()
      } else {
        try {
          recognition.start()
        } catch {
          setStatus('Cannot start microphone. Type request and press Send.')
        }
      }
      return
    }

    if (preview.trim()) {
      processTranscript(preview)
      return
    }
    setStatus('Voice input unavailable. Type request and press Send.')
  }

  function handleCapturedTranscript(transcript) {
    const text = String(transcript || '').trim()
    if (!text) return

    if (memory.pendingQuestion) {
      setQuestionInput(text)
      submitPendingQuestion(text)
      return
    }

    setPreview(text)
    processTranscript(text)
  }

  function persistResponseState(payload, userText, assistantText) {
    setMemory((current) => {
      let next = {
        ...current,
        lastQuestion: userText,
        lastIntent: payload.intent || current.lastIntent,
        lastTopic: payload.topic || current.lastTopic,
        lastConcept: payload.concept || current.lastConcept,
        languagePreference: 'en',
        pendingData: payload.pendingData || current.pendingData,
        pendingActionId: payload.pendingActionId || null,
        confirmationStatus: payload.pendingActionId ? 'awaiting' : 'none',
        pendingQuestion: Boolean(payload.pendingQuestion),
        pendingQuestionPrompt: payload.pendingQuestion ? (payload.questionPrompt || assistantText) : '',
      }
      next = appendConversationTurn(next, 'user', userText, { pageName: pageContext.pageName })
      next = appendConversationTurn(next, 'assistant', assistantText, payload)
      return next
    })
  }

  async function processTranscript(transcript, options = {}) {
    const text = String(transcript || '').trim()
    if (!text) {
      setStatus('Enter or speak a request first.')
      return
    }

    setMemory((current) => ({ ...current, lastQuestion: text }))
    setStatus('Interpreting request...')

    try {
      const response = await fetch(`${AI_API_BASE}/interpret`, {
        method: 'POST',
        credentials: 'include',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          transcript: text,
          context: buildAssistantContext({
            pathname: location.pathname,
            userRole,
            memory: { ...memory, lastQuestion: text },
            pageTitle: typeof document !== 'undefined' ? document.title : '',
          }),
          history: (memory.conversationHistory || []).slice(-6),
        }),
      })

      const payload = await response.json()
      const responseText = String(payload?.confirmationPrompt || payload?.responseText || payload?.message || 'Request processed.')

      if (!response.ok || !payload?.success) {
        persistResponseState(payload || {}, text, responseText)
        setPreview(responseText)
        setStatus(responseText)
        if (!payload?.pendingQuestion) {
          setQuestionInput('')
        }
        return
      }

      persistResponseState(payload, text, responseText)
      setPreview(responseText)
      setStatus(responseText)
      if (options.fromPendingQuestion) {
        setQuestionInput('')
      }

      if (payload?.intent === 'add_truck' && payload?.result?.truck) {
        dispatchTruckUpdate(payload.result.truck)
      }

      const targetRoute = payload?.targetRoute || payload?.result?.targetRoute
      if (payload?.autoNavigated && targetRoute) {
        window.location.assign(targetRoute)
      }
    } catch {
      setStatus('Interpretation request failed.')
    }
  }

  async function confirmPendingAction() {
    if (!memory.pendingActionId) {
      setStatus('No pending action to confirm.')
      return
    }

    setStatus('Applying confirmed action...')
    try {
      const response = await fetch(`${AI_API_BASE}/confirm`, {
        method: 'POST',
        credentials: 'include',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          pendingActionId: memory.pendingActionId,
          confirmation: true,
          context: buildAssistantContext({
            pathname: location.pathname,
            userRole,
            memory,
            pageTitle: typeof document !== 'undefined' ? document.title : '',
          }),
        }),
      })
      const payload = await response.json()
      if (!response.ok || !payload?.success) {
        setStatus(payload?.message || 'Confirmation failed.')
        return
      }

      const mapped = Array.isArray(payload?.mappedFields)
        ? payload.mappedFields
        : payload?.result?.mappedFields || []
      if (mapped.length) {
        applyMappedFields(mapped)
      }

      const message = String(payload?.result?.message || payload?.message || 'Action completed.')
      setMemory((current) => ({
        ...current,
        pendingActionId: null,
        confirmationStatus: 'confirmed',
        pendingData: payload?.pendingData || {},
        pendingQuestion: Boolean(payload?.pendingQuestion),
        pendingQuestionPrompt: payload?.pendingQuestion ? (payload?.questionPrompt || message) : '',
      }))
      setPreview(message)
      setStatus(payload?.questionPrompt || message)

      if (payload?.result?.truck) {
        dispatchTruckUpdate(payload.result.truck)
      }

      const targetRoute = payload?.result?.targetRoute
      if (targetRoute) {
        window.location.assign(targetRoute)
      }
    } catch {
      setStatus('Confirmation request failed.')
    }
  }

  async function cancelPendingAction() {
    if (!memory.pendingActionId) {
      setStatus('No pending action to cancel.')
      return
    }

    try {
      await fetch(`${AI_API_BASE}/cancel`, {
        method: 'POST',
        credentials: 'include',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ pendingActionId: memory.pendingActionId }),
      })
    } catch {
      // no-op
    }

    setMemory((current) => ({
      ...current,
      pendingActionId: null,
      confirmationStatus: 'cancelled',
      pendingData: {},
      pendingQuestion: false,
      pendingQuestionPrompt: '',
    }))
    setQuestionInput('')
    setStatus('Pending action cancelled.')
  }

  function submitPendingQuestion(nextValue = questionInput) {
    const answer = String(nextValue || '').trim()
    if (!answer) {
      setStatus('Please enter or speak an answer first.')
      return
    }
    processTranscript(answer, { fromPendingQuestion: true })
  }

  function openFullChat() {
    navigate(capabilities.chat_page_route || AI_CHAT_ROUTE)
  }

  return (
    <section
      id="aiAssistantWidget"
      className={`ai-assistant-widget mode-${normalizeMode(preferences.mode)}`}
      aria-hidden={preferences.mode === 'hidden' ? 'true' : 'false'}
      data-ai-route={routePath}
    >
      <button
        type="button"
        className="ai-assistant-mini"
        aria-label="Open AI Assistant"
        onClick={() => setPreferences((current) => ({ ...current, mode: 'visible' }))}
      >
        AI
      </button>

      <div className="ai-assistant-shell">
        <div className="ai-assistant-header">
          <span>AI Assistant</span>
          <span className="ai-assistant-pill">{pageContext.pageLabel}</span>
          <div className="ai-assistant-controls">
            <button type="button" className="ai-assistant-btn ai-assistant-btn-ghost" onClick={openFullChat}>
              Chat
            </button>
            <select
              className="ai-assistant-select"
              title="Language"
              value="en"
              disabled
              onChange={() => {}}
            >
              <option value="en">EN</option>
            </select>
            <button type="button" className="ai-assistant-btn ai-assistant-btn-ghost" onClick={cycleVisibilityMode}>
              Mode
            </button>
            <button
              type="button"
              className="ai-assistant-close"
              aria-label="Minimize AI Assistant"
              onClick={() => setPreferences((current) => ({ ...current, mode: 'minimized' }))}
            >
              <i className="fas fa-xmark" aria-hidden="true"></i>
            </button>
          </div>
        </div>

        <div className="ai-assistant-body">
          <textarea
            className="ai-assistant-preview"
            placeholder="Speak or type your command for this page..."
            value={preview}
            onChange={(event) => setPreview(event.target.value)}
            onKeyDown={(event) => {
              if (event.key === 'Enter' && !event.shiftKey) {
                event.preventDefault()
                processTranscript(preview)
              }
            }}
          />

          <div className="ai-assistant-question" hidden={!memory.pendingQuestion}>
            <div className="ai-assistant-question-prompt">
              {memory.pendingQuestionPrompt || 'Please answer the assistant question.'}
            </div>
            <div className="ai-assistant-question-row">
              <input
                className="ai-assistant-question-input"
                type="text"
                placeholder="Type your answer..."
                value={questionInput}
                onChange={(event) => setQuestionInput(event.target.value)}
                onKeyDown={(event) => {
                  if (event.key === 'Enter') {
                    event.preventDefault()
                    submitPendingQuestion()
                  }
                }}
              />
              <button type="button" className={`ai-assistant-btn ai-assistant-btn-mic${isListening ? ' is-recording' : ''}`} onClick={handleMicToggle}>
                {isListening ? 'Stop' : 'Mic'}
              </button>
              <button type="button" className="ai-assistant-btn ai-assistant-btn-send" onClick={() => submitPendingQuestion()}>
                Submit
              </button>
            </div>
          </div>

          <div className="ai-assistant-row">
            <button type="button" className={`ai-assistant-btn ai-assistant-btn-mic${isListening ? ' is-recording' : ''}`} onClick={handleMicToggle}>
              {isListening ? 'Stop' : 'Mic'}
            </button>
            <button type="button" className="ai-assistant-btn ai-assistant-btn-send" onClick={() => processTranscript(preview)}>
              Send
            </button>
            <button type="button" className="ai-assistant-btn ai-assistant-btn-confirm" disabled={!memory.pendingActionId} onClick={confirmPendingAction}>
              Confirm
            </button>
            <button type="button" className="ai-assistant-btn ai-assistant-btn-cancel" disabled={!memory.pendingActionId} onClick={cancelPendingAction}>
              Cancel
            </button>
          </div>

          <label className="ai-assistant-toggle">
            <input
              type="checkbox"
              checked={preferences.backgroundListening}
              onChange={(event) =>
                setPreferences((current) => ({
                  ...current,
                  backgroundListening: Boolean(event.target.checked),
                }))
              }
            />
            Background voice in hidden mode
          </label>

          <div className="ai-assistant-status">{status || `Signed in as ${roleLabel(userRole)}`}</div>
          <div className="ai-assistant-hint">Shortcut: Ctrl + Shift + A</div>
        </div>
      </div>
    </section>
  )
}

import { useEffect, useMemo, useRef, useState } from 'react'
import { formatDateTime, getCsrfToken, apiGet, apiSend } from '../../pages/client/clientUtils'
import '../../styles/components/chat-window.css'

const POLL_INTERVAL_MS = 4000

function statusTone(status) {
  if (status === 'approved' || status === 'fulfilled') return 'text-emerald-700'
  if (status === 'denied') return 'text-red-700'
  return 'text-amber-700'
}

function orderStatusTone(status = '') {
  const normalized = String(status).toLowerCase()
  if (normalized.includes('active') || normalized.includes('approved') || normalized.includes('assigned')) {
    return 'bg-emerald-50 text-emerald-700'
  }
  if (normalized.includes('cancel') || normalized.includes('reject') || normalized.includes('inactive')) {
    return 'bg-red-50 text-red-700'
  }
  return 'bg-gray-100 text-gray-500'
}

function partyInitial(name = '') {
  return String(name).trim().charAt(0).toUpperCase() || 'C'
}

function canRespondToMediaRequest(message, currentUserId) {
  return message.message_type === 'media_request' && !message.is_own && message.media_request_status === 'pending' && message.sender_user_id !== currentUserId
}

function canSendMediaForApproval(message) {
  return message.message_type === 'media_request' && message.is_own && message.media_request_status === 'approved'
}

export default function ChatWindow({ role = 'client', onUnreadChange, initialThreadId = null, heightClass = 'h-[calc(100vh-118px)]' }) {
  const [threads, setThreads] = useState([])
  const [activeThreadId, setActiveThreadId] = useState(null)
  const [messages, setMessages] = useState([])
  const [loadingThreads, setLoadingThreads] = useState(true)
  const [loadingMessages, setLoadingMessages] = useState(false)
  const [sending, setSending] = useState(false)
  const [messageText, setMessageText] = useState('')
  const [error, setError] = useState('')
  const [notice, setNotice] = useState('')
  const [actingOnMessage, setActingOnMessage] = useState('')
  const [uploading, setUploading] = useState(false)
  const [currentUser] = useState(() => {
    const stored = sessionStorage.getItem('user')
    if (!stored) return null
    try {
      return JSON.parse(stored)
    } catch {
      return null
    }
  })
  const [searchTerm, setSearchTerm] = useState('')
  const fileInputRef = useRef(null)
  const activeThread = useMemo(
    () => threads.find((thread) => thread.id === activeThreadId) || null,
    [threads, activeThreadId],
  )
  const visibleThreads = useMemo(() => {
    const query = searchTerm.trim().toLowerCase()
    if (!query) return threads
    return threads.filter((thread) => {
      const haystack = [
        thread.other_party_name,
        thread.order?.id,
        thread.order?.route_label,
        thread.order?.status,
        thread.last_message_preview,
      ].join(' ').toLowerCase()
      return haystack.includes(query)
    })
  }, [searchTerm, threads])

  const currentUserId = currentUser?.id ?? null
  const totalUnread = useMemo(
    () => threads.reduce((sum, thread) => sum + Number(thread.unread_count || 0), 0),
    [threads],
  )

  useEffect(() => {
    onUnreadChange?.(totalUnread)
  }, [onUnreadChange, totalUnread])

  async function loadThreads(preferredThreadId = null, { silent = false } = {}) {
    if (!silent) setLoadingThreads(true)
    try {
      const json = await apiGet('/api/chat/threads')
      const nextThreads = json.threads || []
      setThreads(nextThreads)
      setError('')
      setActiveThreadId((current) => {
        if (preferredThreadId && nextThreads.some((thread) => thread.id === preferredThreadId)) return preferredThreadId
        if (current && nextThreads.some((thread) => thread.id === current)) return current
        return nextThreads[0]?.id || null
      })
    } catch (loadError) {
      setError(loadError.message || 'Unable to load chats.')
    } finally {
      if (!silent) setLoadingThreads(false)
    }
  }

  async function loadMessages(threadId, afterId = null, { silent = false } = {}) {
    if (!threadId) return
    if (!silent) setLoadingMessages(true)
    try {
      const suffix = afterId ? `?after_id=${afterId}` : ''
      const json = await apiGet(`/api/chat/threads/${threadId}/messages${suffix}`)
      const incoming = json.messages || []
      setMessages((current) => {
        if (!afterId) return incoming
        if (!incoming.length) return current
        const knownIds = new Set(current.map((item) => item.id))
        const appended = incoming.filter((item) => !knownIds.has(item.id))
        return appended.length ? [...current, ...appended] : current
      })
      setThreads((current) => current.map((thread) => (
        thread.id === threadId
          ? {
              ...thread,
              unread_count: 0,
              last_message_at: incoming.length ? incoming[incoming.length - 1].created_at : thread.last_message_at,
            }
          : thread
      )))
      setError('')
    } catch (loadError) {
      if (!silent) setError(loadError.message || 'Unable to load messages.')
    } finally {
      if (!silent) setLoadingMessages(false)
    }
  }

  useEffect(() => {
    // eslint-disable-next-line react-hooks/set-state-in-effect
    loadThreads(initialThreadId ? Number(initialThreadId) : null)
  }, [initialThreadId])

  useEffect(() => {
    if (!activeThreadId) {
      // eslint-disable-next-line react-hooks/set-state-in-effect
      setMessages([])
      return
    }
    loadMessages(activeThreadId)
  }, [activeThreadId])

  useEffect(() => {
    if (!activeThreadId) return undefined
    const intervalId = window.setInterval(() => {
      // If there are pending media requests in chat, do a full sync to catch approval/denial status updates
      const hasPendingMediaRequest = messages.some(
        (m) => m.message_type === 'media_request' && m.media_request_status === 'pending'
      )
      const lastId = hasPendingMediaRequest ? null : (messages[messages.length - 1]?.id || 0)
      loadMessages(activeThreadId, lastId, { silent: true })
      loadThreads(activeThreadId, { silent: true })
    }, POLL_INTERVAL_MS)
    return () => window.clearInterval(intervalId)
  }, [activeThreadId, messages])

  async function sendTextMessage(event) {
    event.preventDefault()
    const content = messageText.trim()
    if (!activeThreadId || !content) return

    setSending(true)
    setNotice('')
    try {
      const json = await apiSend(`/api/chat/threads/${activeThreadId}/messages`, {
        message_type: 'text',
        content,
      })
      setMessages((current) => [...current, json.message])
      setMessageText('')
      await loadThreads(activeThreadId, { silent: true })
    } catch (sendError) {
      setError(sendError.message || 'Unable to send message.')
    } finally {
      setSending(false)
    }
  }

  async function sendMediaRequest() {
    if (!activeThreadId) return
    setActingOnMessage('request')
    setNotice('')
    try {
      const json = await apiSend(`/api/chat/threads/${activeThreadId}/messages`, {
        message_type: 'media_request',
        content: 'Can I send you a photo/video?',
      })
      setMessages((current) => [...current, json.message])
      await loadThreads(activeThreadId, { silent: true })
    } catch (requestError) {
      setError(requestError.message || 'Unable to request media permission.')
    } finally {
      setActingOnMessage('')
    }
  }

  async function respondToRequest(messageId, action) {
    if (!activeThreadId) return
    setActingOnMessage(`${action}:${messageId}`)
    setNotice('')
    try {
      const json = await apiSend(`/api/chat/threads/${activeThreadId}/messages/${messageId}/respond-media-request`, { action })
      setNotice(json.message || 'Request updated.')
      await loadMessages(activeThreadId)
      await loadThreads(activeThreadId, { silent: true })
    } catch (actionError) {
      setError(actionError.message || 'Unable to update media request.')
    } finally {
      setActingOnMessage('')
    }
  }

  async function uploadMediaFile(event) {
    const file = event.target.files?.[0]
    if (!file || !activeThreadId) return

    setUploading(true)
    setNotice('')
    try {
      const csrf = await getCsrfToken()
      const formData = new FormData()
      formData.append('media', file)
      const response = await fetch(`/api/chat/threads/${activeThreadId}/messages/media`, {
        method: 'POST',
        credentials: 'same-origin',
        headers: { 'X-CSRF-Token': csrf },
        body: formData,
      })
      const json = await response.json().catch(() => ({}))
      if (!response.ok || json.success === false) {
        throw new Error(json.message || 'Unable to upload media.')
      }
      setMessages((current) => [...current, json.message])
      await loadThreads(activeThreadId, { silent: true })
      await loadMessages(activeThreadId)
    } catch (uploadError) {
      setError(uploadError.message || 'Unable to upload media.')
    } finally {
      event.target.value = ''
      setUploading(false)
    }
  }

  const approvedRequest = useMemo(
    () => messages.find((message) => canSendMediaForApproval(message)),
    [messages],
  )

  const scrollPaneClass = '[scrollbar-width:thin] [scrollbar-color:#D1D5DB_transparent] [&::-webkit-scrollbar]:w-1 [&::-webkit-scrollbar-track]:bg-transparent [&::-webkit-scrollbar-thumb]:rounded-full [&::-webkit-scrollbar-thumb]:bg-gray-300'

  return (
    <div className={`chat-window grid ${heightClass} min-h-0 overflow-hidden rounded-2xl bg-white shadow-[0px_4px_6px_-1px_rgba(0,0,0,0.1)] lg:grid-cols-[34%_66%]`}>
      <section className="chat-sidebar flex min-h-0 flex-col border-gray-100 lg:border-r">
        <div className="chat-sidebar-header sticky top-0 z-10 flex-shrink-0 space-y-4 border-b border-gray-100 bg-white p-5">
          <div className="chat-title-row flex items-center justify-between gap-3">
            <h1 className="chat-title text-2xl font-bold text-[#111827]">Chats</h1>
            <span className="chat-count-pill rounded-full bg-indigo-100 px-3 py-1 text-xs font-semibold text-indigo-700">
              {totalUnread || threads.length}
            </span>
          </div>
          <label className="chat-search flex min-h-11 items-center gap-3 rounded-lg border border-[#E5E7EB] bg-gray-50 px-3 text-[#6B7280]">
            <i className="fas fa-search text-sm" aria-hidden="true"></i>
            <input
              type="search"
              value={searchTerm}
              onChange={(event) => setSearchTerm(event.target.value)}
              placeholder="Search chats..."
              className="h-full min-w-0 flex-1 border-0 bg-transparent text-sm text-[#111827] outline-none placeholder:text-[#6B7280]"
            />
          </label>
        </div>

        <div className={`chat-thread-list min-h-0 flex-1 overflow-y-auto ${scrollPaneClass}`}>
          {loadingThreads && <div className="chat-state-card m-5 rounded-lg bg-[#F3F4F6] px-4 py-5 text-sm text-[#6B7280]">Loading chats...</div>}
          {!loadingThreads && threads.length === 0 && (
            <div className="chat-state-card m-5 rounded-lg border border-dashed border-[#E5E7EB] bg-gray-50 px-4 py-8 text-center text-sm text-[#6B7280]">
              No chat threads yet. A thread is created automatically when a bid is placed.
            </div>
          )}
          {!loadingThreads && threads.length > 0 && visibleThreads.length === 0 && (
            <div className="chat-state-card m-5 rounded-lg bg-gray-50 px-4 py-8 text-center text-sm text-[#6B7280]">
              No chats match your search.
            </div>
          )}
          {!loadingThreads && visibleThreads.map((thread) => {
            const active = thread.id === activeThreadId
            const status = thread.order?.status || 'Inactive'
            return (
              <button
                key={thread.id}
                type="button"
                onClick={() => setActiveThreadId(thread.id)}
                className={`chat-thread-item flex w-full items-start gap-3 border-b border-gray-100 px-5 py-4 text-left transition ${
                  active ? 'chat-thread-item--active bg-indigo-50/70' : 'bg-white hover:bg-gray-50'
                }`}
              >
                <span className="chat-avatar grid h-11 w-11 shrink-0 place-items-center rounded-full bg-indigo-100 text-sm font-bold text-indigo-700">
                  {partyInitial(thread.other_party_name)}
                </span>
                <span className="chat-thread-content min-w-0 flex-1">
                  <span className="flex items-start justify-between gap-3">
                    <span className="min-w-0">
