import { useEffect, useRef, useState } from 'react'
import L from 'leaflet'
import 'leaflet/dist/leaflet.css'

/*
 * LocationPicker
 * One detailed address input + a map button. Typing an address and pressing
 * "Locate" geocodes it (OpenStreetMap / Nominatim) and drops a pin. If the map
 * gets it wrong, the user can click anywhere on the map or drag the pin to the
 * exact spot - the address text and coordinates update to match.
 *
 * Uses the installed Leaflet package with OpenStreetMap tiles (no API key).
 *
 * value:    { location: string, lat: number|null, lng: number|null }
 * onChange: (nextValue) => void
 */

const PAKISTAN_CENTER = [30.3753, 69.3451]

export default function LocationPicker({ label, value, onChange, required = false, placeholder }) {
  const val = value || { location: '', lat: null, lng: null }
  const [showMap, setShowMap] = useState(false)
  const [busy, setBusy] = useState(false)
  const [note, setNote] = useState('')

  const mapDivRef = useRef(null)
  const mapRef = useRef(null)
  const markerRef = useRef(null)
  const valRef = useRef(val)
  valRef.current = val


  // Initialise / tear down the map when it becomes visible.
  useEffect(() => {
    if (!showMap || !mapDivRef.current || mapRef.current) return
    const start = valRef.current.lat != null ? [valRef.current.lat, valRef.current.lng] : PAKISTAN_CENTER
    const zoom = valRef.current.lat != null ? 14 : 5
    const map = L.map(mapDivRef.current).setView(start, zoom)
    L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png', {
      maxZoom: 19,
      attribution: '&copy; OpenStreetMap',
    }).addTo(map)

    const icon = L.divIcon({
      html: '<i class="fas fa-map-marker-alt" style="font-size:34px;color:#2563eb;text-shadow:0 2px 4px rgba(0,0,0,.35)"></i>',
      className: 'lp-pin',
      iconSize: [34, 34],
      iconAnchor: [17, 32],
    })

    function placeMarker(lat, lng, reverse) {
      if (!markerRef.current) {
        markerRef.current = L.marker([lat, lng], { draggable: true, icon }).addTo(map)
        markerRef.current.on('dragend', () => {
          const p = markerRef.current.getLatLng()
          commit(p.lat, p.lng, true)
        })
      } else {
        markerRef.current.setLatLng([lat, lng])
      }
      if (reverse) reverseGeocode(lat, lng)
    }

    function commit(lat, lng, reverse) {
      onChange({ ...valRef.current, lat: Number(lat.toFixed(6)), lng: Number(lng.toFixed(6)) })
      placeMarker(lat, lng, reverse)
    }

    map.on('click', (e) => commit(e.latlng.lat, e.latlng.lng, true))
    mapRef.current = map
    if (valRef.current.lat != null) placeMarker(valRef.current.lat, valRef.current.lng, false)
    setTimeout(() => map.invalidateSize(), 120)

    return () => {
      map.remove()
      mapRef.current = null
      markerRef.current = null
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [showMap])

  async function reverseGeocode(lat, lng) {
    try {
      const res = await fetch(`https://nominatim.openstreetmap.org/reverse?format=json&lat=${lat}&lon=${lng}`, {
        headers: { Accept: 'application/json' },
      })
      const data = await res.json()
      if (data && data.display_name) {
        onChange({ ...valRef.current, location: data.display_name, lat: Number(lat.toFixed(6)), lng: Number(lng.toFixed(6)) })
      }
    } catch (_) { /* keep typed text */ }
  }

  async function locateOnMap() {
    setNote('')
    if (!showMap) setShowMap(true)
    const query = (valRef.current.location || '').trim()
    if (!query) {
      setNote('Type an address first, or click on the map to drop a pin.')
      return
    }
    setBusy(true)
    try {
      const res = await fetch(
        `https://nominatim.openstreetmap.org/search?format=json&countrycodes=pk&limit=1&q=${encodeURIComponent(query)}`,
        { headers: { Accept: 'application/json' } },
      )
      const results = await res.json()
      if (results && results.length) {
        const { lat, lon } = results[0]
        const la = Number(lat), lo = Number(lon)
        onChange({ ...valRef.current, lat: Number(la.toFixed(6)), lng: Number(lo.toFixed(6)) })
        const map = mapRef.current
        if (map) {
          map.setView([la, lo], 15)
          if (markerRef.current) markerRef.current.setLatLng([la, lo])
          else map.fire('click', { latlng: { lat: la, lng: lo } })
        }
        setNote('Pin placed. Drag it or click the map to adjust.')
      } else {
        setNote('Location not found on map. Click on the map to place the pin manually.')
      }
    } catch (_) {
      setNote('Could not search the map right now. You can still place the pin manually.')
    } finally {
      setBusy(false)
    }
  }

  return (
    <div className="lp-field">
      <label className="lp-label">
        {label}{required ? ' *' : ''}
      </label>
      <div className="lp-input-row">
        <input
          className="lp-input"
          value={val.location}
          onChange={(e) => onChange({ ...val, location: e.target.value })}
          placeholder={placeholder || 'House / shop, street, area, city'}
          required={required}
        />
        <button type="button" className="lp-map-btn" onClick={locateOnMap} disabled={busy} title="Locate on map">
          <i className={`fas ${busy ? 'fa-spinner fa-spin' : 'fa-map-location-dot'}`} aria-hidden="true"></i>
          <span>{showMap ? 'Locate' : 'Map'}</span>
        </button>
      </div>

      {val.lat != null && (
        <div className="lp-coords">
          <i className="fas fa-location-crosshairs" aria-hidden="true"></i>
          {val.lat.toFixed(5)}, {val.lng.toFixed(5)}
          <button type="button" className="lp-toggle" onClick={() => setShowMap((s) => !s)}>
            {showMap ? 'Hide map' : 'Show map'}
          </button>
        </div>
      )}

      {note && <div className="lp-note">{note}</div>}
      {showMap && <div ref={mapDivRef} className="lp-map" />}
    </div>
  )
}

import useEverydayAuth from '../../hooks/useEverydayAuth'

// Gates the /everyday/* surface: everyday users pass; business seekers are
// redirected to /client/*, and unauthenticated users to /login (handled inside
// useEverydayAuth). Mirrors ClientGuard's loading UX.
export default function EverydayGuard({ children }) {
  const { ready, user, status } = useEverydayAuth()

  if (!ready) {
    return (
      <div className="flex min-h-screen flex-col items-center justify-center gap-3 bg-slate-50">
        <div className="h-8 w-8 animate-spin rounded-full border-4 border-blue-600 border-t-transparent" />
        <p className="text-sm text-slate-500">Checking session...</p>
      </div>
    )
  }

  return children
}

import { createContext, useCallback, useEffect, useMemo, useRef, useState } from 'react'
import { useLocation, useNavigate } from 'react-router-dom'
import {
  ACCESS_STATES,
  accessLockCoordinator,
  authorityContextKey,
  createLatestRequestGate,
  deriveAccessState,
  isPublicAuthPath,
  safeRelativePath,
} from '../../auth/accessLock'
import { ApiResponseError, requestJson } from '../../auth/api'
import { AUTH_STATUSES, AuthVerificationProvider } from '../../auth/AuthVerificationContext'
import { bootstrapAuth, cacheAuthPresentation, clearAuthPresentation, currentPresentedUser } from '../../auth/presentation'
import MpinInput from './MpinInput'
import '../../styles/components/mpin-security.css'

const AccessLockContext = createContext(null)
const AUTH_FRESHNESS_MS = 15 * 60 * 1000

function parseBootstrapTime(value) {
  const stamp = Date.parse(value || '')
  return Number.isFinite(stamp) ? stamp : 0
}

function initialAuthorityFromBootstrap() {
  const auth = bootstrapAuth()
  const presentedUser = currentPresentedUser()
  if (!auth) {
    return {
      state: ACCESS_STATES.CHECKING,
      user: presentedUser,
      hasPresentation: Boolean(presentedUser?.id),
      freshUntil: 0,
      verifiedAt: 0,
    }
  }
  const status = String(auth.status || '').trim().toLowerCase()
  const freshUntil = parseBootstrapTime(auth.fresh_until)
  const verifiedAt = parseBootstrapTime(auth.verified_at)
  if (status === 'unlocked' && auth.user?.id && freshUntil > Date.now()) {
    return {
      state: ACCESS_STATES.UNLOCKED,
      user: auth.user,
      hasPresentation: true,
      freshUntil,
      verifiedAt: verifiedAt || Date.now(),
    }
  }
  if (status === 'locked' && auth.user?.id) {
    return {
      state: ACCESS_STATES.LOCKED_PASSWORD_REQUIRED,
      user: auth.user,
      hasPresentation: true,
      freshUntil,
      verifiedAt: verifiedAt || Date.now(),
    }
  }
  return {
    state: ACCESS_STATES.FULL_LOGIN_REQUIRED,
    user: null,
    hasPresentation: false,
    freshUntil,
    verifiedAt,
  }
}

function genericUnlockMessage(error, kind) {
  if (error?.status === 503) return 'Unlock is temporarily unavailable. Please try again.'
  if (kind === 'mpin' && error?.status === 401) return 'The MPIN could not be verified.'
  if (kind === 'password' && error?.status === 401) return 'The password could not be verified.'
  return 'Unlock could not be completed. Please try again.'
}

function AccessLockScreen({ state, user, onRefresh }) {
  const navigate = useNavigate()
  const headingRef = useRef(null)
  const mpinRef = useRef(null)
  const dialogRef = useRef(null)
  const [mode, setMode] = useState(() => state === ACCESS_STATES.LOCKED_MPIN_AVAILABLE ? 'mpin' : 'password')
  const [mpin, setMpin] = useState('')
  const [password, setPassword] = useState('')
  const [error, setError] = useState('')
  const [pending, setPending] = useState(false)

  const permanent = state === ACCESS_STATES.MPIN_PERMANENTLY_LOCKED
  const mpinAvailable = state === ACCESS_STATES.LOCKED_MPIN_AVAILABLE && mode === 'mpin'
  const unavailable = state === ACCESS_STATES.TEMPORARILY_UNAVAILABLE

  useEffect(() => {
    window.requestAnimationFrame(() => {
      if (state === ACCESS_STATES.LOCKED_MPIN_AVAILABLE) mpinRef.current?.focus()
      else headingRef.current?.focus()
    })
  }, [state])

  function trapFocus(event) {
    if (event.key === 'Escape') {
      event.preventDefault()
      return
    }
    if (event.key !== 'Tab') return
    const focusable = [...dialogRef.current.querySelectorAll(
      'button:not([disabled]), input:not([disabled]), a[href], [tabindex="0"]',
    )]
    if (!focusable.length) return
    const first = focusable[0]
    const last = focusable[focusable.length - 1]
    if (event.shiftKey && document.activeElement === first) {
      event.preventDefault()
      last.focus()
    } else if (!event.shiftKey && document.activeElement === last) {
      event.preventDefault()
      first.focus()
    }
  }

  async function submitMpin(event) {
    event.preventDefault()
    if (!/^[0-9]{4}$/.test(mpin) || pending) {
      if (!pending) setError('Enter exactly four digits.')
      return
    }
    setPending(true)
    setError('')
    try {
      await requestJson('/auth/mpin/unlock', { method: 'POST', body: { mpin } })
      setMpin('')
      await onRefresh()
    } catch (requestError) {
      setMpin('')
      if (requestError instanceof ApiResponseError && requestError.status === 423 && requestError.code === 'mpin_locked') {
        await onRefresh()
      } else if (requestError instanceof ApiResponseError && requestError.status === 409) {
        await onRefresh()
      } else {
        setError(genericUnlockMessage(requestError, 'mpin'))
        window.requestAnimationFrame(() => mpinRef.current?.focus())
      }
    } finally {
      setPending(false)
    }
  }

  async function submitPassword(event) {
    event.preventDefault()
    if (!password || pending) return
    const identifier = user?.email || user?.cnic || ''
    if (!identifier) {
      setError('Password unlock is temporarily unavailable. Please sign in again.')
      return
    }
    setPending(true)
    setError('')
    try {
      await requestJson('/auth/access/unlock/password', {
        method: 'POST',
        body: { identifier, password },
      })
      setPassword('')
      await onRefresh()
    } catch (requestError) {
      setPassword('')
      if (requestError instanceof ApiResponseError && requestError.status === 409) {
        await onRefresh()
      } else {
        setError(genericUnlockMessage(requestError, 'password'))
      }
    } finally {
      setPending(false)
    }
  }

  async function logout() {
    setPending(true)
    try {
      await requestJson('/auth/logout', { method: 'POST' })
    } catch {
      // Local presentation cleanup is required even if logout persistence fails.
    } finally {
      clearAuthPresentation()
      accessLockCoordinator.notifyFullLoginRequired()
      navigate('/login', { replace: true })
      setPending(false)
    }
  }

  const title = permanent ? 'MPIN locked' : unavailable ? 'Unlock temporarily unavailable' : 'Digi_TransX is locked'
  const description = permanent
    ? 'Your MPIN is permanently locked. Verify your password to unlock, then reset the MPIN in Security settings.'
    : unavailable
      ? 'We could not confirm MPIN status. You can retry or unlock with your password.'
      : 'Your signed-in session is still valid. Unlock access to continue.'

  return (
    <div className="access-lock" role="presentation">
      <section
        ref={dialogRef}
        className="access-lock__dialog"
        role="dialog"
        aria-modal="true"
        aria-labelledby="access-lock-title"
        aria-describedby="access-lock-description"
        onKeyDown={trapFocus}
      >
        <div className="access-lock__icon" aria-hidden="true"><i className="fas fa-lock" /></div>
        <h1 id="access-lock-title" ref={headingRef} tabIndex={-1}>{title}</h1>
        <p id="access-lock-description">{description}</p>

        {mpinAvailable ? (
          <form onSubmit={submitMpin} className="access-lock__form">
            <MpinInput ref={mpinRef} value={mpin} onChange={setMpin} disabled={pending} errorId={error ? 'access-lock-error' : undefined} />
            {error && <p id="access-lock-error" className="security-message is-error" role="alert">{error}</p>}
            <button className="security-primary" type="submit" disabled={pending || mpin.length !== 4}>
              {pending ? 'Unlocking…' : 'Unlock'}
            </button>
            <button className="security-link" type="button" disabled={pending} onClick={() => { setMode('password'); setError(''); setMpin('') }}>
              Unlock with password
            </button>
          </form>
        ) : (
          <form onSubmit={submitPassword} className="access-lock__form">
            {!unavailable && <p className="access-lock__account">Unlocking the current signed-in account</p>}
            <label className="security-field" htmlFor="access-unlock-password">
              <span>Password</span>
              <input
                id="access-unlock-password"
                type="password"
                autoComplete="current-password"
                value={password}
                onChange={(event) => setPassword(event.target.value)}
                disabled={pending}
              />
            </label>
            {error && <p id="access-lock-error" className="security-message is-error" role="alert">{error}</p>}
            <button className="security-primary" type="submit" disabled={pending || !password}>
              {pending ? 'Verifying…' : 'Unlock with password'}
            </button>
            {state === ACCESS_STATES.LOCKED_PASSWORD_REQUIRED && !permanent && (
              <p className="access-lock__note">MPIN is not available for this account.</p>
            )}
            {state === ACCESS_STATES.LOCKED_MPIN_AVAILABLE && (
              <button className="security-link" type="button" disabled={pending} onClick={() => { setMode('mpin'); setError(''); setPassword('') }}>
                Use MPIN instead
              </button>
            )}
          </form>
        )}

        {unavailable && (
          <button className="security-secondary" type="button" disabled={pending} onClick={() => onRefresh()}>
            Retry status check
          </button>
        )}
        <button className="security-logout" type="button" disabled={pending} onClick={logout}>
          <i className="fas fa-sign-out-alt" aria-hidden="true" /> Log out
        </button>
      </section>
    </div>
  )
}

export default function AccessLockProvider({ children }) {
  const location = useLocation()
  const navigate = useNavigate()
  const initialAuthority = useMemo(() => initialAuthorityFromBootstrap(), [])
  const [state, setState] = useState(initialAuthority.state)
  const [user, setUser] = useState(initialAuthority.user)
  const [hasPresentation, setHasPresentation] = useState(initialAuthority.hasPresentation)
  const [showChecking, setShowChecking] = useState(false)
  const gate = useRef(createLatestRequestGate())
  const controller = useRef(null)
  const authorityContext = useRef(null)
  const lastVerifiedAt = useRef(initialAuthority.verifiedAt)
  const freshUntil = useRef(initialAuthority.freshUntil)
  const refreshInFlight = useRef(null)
  const locationPath = useRef(location.pathname)

  useEffect(() => {
    locationPath.current = location.pathname
  }, [location.pathname])

  const requireFullLogin = useCallback((returnPath = locationPath.current) => {
    controller.current?.abort()
    gate.current.invalidate()
    refreshInFlight.current = null
    setState(ACCESS_STATES.FULL_LOGIN_REQUIRED)
    setUser(null)
    setHasPresentation(false)
    lastVerifiedAt.current = 0
    freshUntil.current = 0
    authorityContext.current = null
    clearAuthPresentation()
    const safePath = safeRelativePath(returnPath)
    if (!isPublicAuthPath(locationPath.current)) {
      navigate('/login', { replace: true, state: { returnPath: safePath } })
    }
  }, [navigate])

  const refreshAuthority = useCallback(async ({ force = false } = {}) => {
    if (!force && isPublicAuthPath(locationPath.current) && !hasPresentation) {
      setState(ACCESS_STATES.FULL_LOGIN_REQUIRED)
      return undefined
    }
    if (refreshInFlight.current) return refreshInFlight.current
    controller.current?.abort()
    const requestController = new AbortController()
    controller.current = requestController
    const revision = gate.current.begin()
    const task = (async () => {
      try {
      const auth = await requestJson('/auth/me', { signal: requestController.signal })
      if (!gate.current.isCurrent(revision)) return
      const now = Date.now()
      lastVerifiedAt.current = now
      freshUntil.current = Math.min(
        parseBootstrapTime(auth.fresh_until) || now + AUTH_FRESHNESS_MS,
        now + AUTH_FRESHNESS_MS,
      )
      const nextAuthorityContext = authorityContextKey(auth)
      const previousAuthorityContext = authorityContext.current
      authorityContext.current = nextAuthorityContext
      if (previousAuthorityContext !== null && previousAuthorityContext !== nextAuthorityContext) {
        accessLockCoordinator.notifyIdentityContextChanged()
      }
      setUser(auth.user)
      setHasPresentation(Boolean(auth.user?.id))
      cacheAuthPresentation(auth)
      if (!auth.access_locked) {
        setState(ACCESS_STATES.UNLOCKED)
        await accessLockCoordinator.markUnlocked()
        return
      }
      try {
        const status = await requestJson('/auth/mpin/status', { signal: requestController.signal })
        if (!gate.current.isCurrent(revision)) return
        setState(deriveAccessState({ authenticated: true, accessLocked: true, mpinStatus: status.mpin }))
      } catch (error) {
        if (!gate.current.isCurrent(revision) || error?.name === 'AbortError') return
        if (error?.status === 401) requireFullLogin()
        else setState(deriveAccessState({ authenticated: true, accessLocked: true, statusUnavailable: true }))
      }
    } catch (error) {
      if (!gate.current.isCurrent(revision) || error?.name === 'AbortError') return
      if (error?.status === 401) requireFullLogin()
      else if (isPublicAuthPath(location.pathname)) {
        setState(ACCESS_STATES.FULL_LOGIN_REQUIRED)
      } else {
        setState((current) => current === ACCESS_STATES.UNLOCKED ? current : ACCESS_STATES.TEMPORARILY_UNAVAILABLE)
      }
    }
    })().finally(() => {
      if (refreshInFlight.current === task) refreshInFlight.current = null
    })
    refreshInFlight.current = task
    return task
  }, [hasPresentation, location.pathname, requireFullLogin])

  useEffect(() => {
    const timer = window.setTimeout(() => { refreshAuthority() }, 0)
    return () => {
      window.clearTimeout(timer)
      controller.current?.abort()
      accessLockCoordinator.cancelReplay()
    }
  }, [])

  useEffect(() => {
    if (state === ACCESS_STATES.FULL_LOGIN_REQUIRED && !isPublicAuthPath(location.pathname)) {
      requireFullLogin(location.pathname)
    }
  }, [location.pathname, requireFullLogin, state])

  useEffect(() => {
    function refreshIfStale() {
      if (document.visibilityState === 'hidden') return
      if (isPublicAuthPath(locationPath.current) && !hasPresentation) return
      const now = Date.now()
      const stale = now >= freshUntil.current || now - lastVerifiedAt.current >= AUTH_FRESHNESS_MS
      if (stale) refreshAuthority()
    }
    window.addEventListener('focus', refreshIfStale)
    document.addEventListener('visibilitychange', refreshIfStale)
    return () => {
      window.removeEventListener('focus', refreshIfStale)
      document.removeEventListener('visibilitychange', refreshIfStale)
    }
  }, [hasPresentation, refreshAuthority])

  useEffect(() => {
    if (state !== ACCESS_STATES.CHECKING || hasPresentation) return undefined
    const timer = window.setTimeout(() => setShowChecking(true), 400)
    return () => window.clearTimeout(timer)
  }, [hasPresentation, state])

  useEffect(() => accessLockCoordinator.subscribe((event) => {
    if (event.type === 'access_locked') refreshAuthority()
    if (event.type === 'full_login_required') requireFullLogin(event.returnPath)
  }), [refreshAuthority, requireFullLogin])

  const blocked = [
    ACCESS_STATES.LOCKED_MPIN_AVAILABLE,
    ACCESS_STATES.LOCKED_PASSWORD_REQUIRED,
    ACCESS_STATES.MPIN_PERMANENTLY_LOCKED,
    ACCESS_STATES.TEMPORARILY_UNAVAILABLE,
  ].includes(state)

  const value = useMemo(() => ({ state, user, refreshAuthority }), [state, user, refreshAuthority])
  const authStatus = useMemo(() => {
    if (state === ACCESS_STATES.UNLOCKED) return AUTH_STATUSES.VERIFIED
    if (state === ACCESS_STATES.FULL_LOGIN_REQUIRED) return AUTH_STATUSES.UNAUTHORIZED
    if (state === ACCESS_STATES.TEMPORARILY_UNAVAILABLE) return AUTH_STATUSES.TEMPORARILY_UNAVAILABLE
    if (blocked) return AUTH_STATUSES.LOCKED
    if (hasPresentation && user?.id) return AUTH_STATUSES.PRESENTED
    return AUTH_STATUSES.CHECKING
  }, [blocked, hasPresentation, state, user])
  const authValue = useMemo(() => ({ status: authStatus, user, refreshAuthority }), [authStatus, user, refreshAuthority])

  return (
    <AccessLockContext.Provider value={value}>
      <AuthVerificationProvider value={authValue}>
        <div className="access-lock__application" inert={blocked ? true : undefined} aria-hidden={blocked ? 'true' : undefined}>
          {children}
        </div>
      </AuthVerificationProvider>
      {state === ACCESS_STATES.CHECKING && !hasPresentation && showChecking && (
        <div className="access-lock access-lock--checking" role="status" aria-live="polite">
          <div className="access-lock__checking-card">
            <span className="access-lock__spinner" aria-hidden="true" />
            <span>Checking secure access...</span>
          </div>
        </div>
      )}
      {blocked && state !== ACCESS_STATES.CHECKING && <AccessLockScreen key={state} state={state} user={user} onRefresh={refreshAuthority} />}
    </AccessLockContext.Provider>
  )
}

import { createContext, useCallback, useContext, useEffect, useRef, useState } from 'react'
import { ApiResponseError, requestJson } from '../../auth/api'
import { accessLockCoordinator } from '../../auth/accessLock'
import { currentPresentedUser } from '../../auth/presentation'
import { useLocation, useNavigate } from 'react-router-dom'
import MpinInput from './MpinInput'
import '../../styles/components/mpin-security.css'

const StepUpContext = createContext(null)

export function securitySetupPathForRole(role) {
  const normalized = String(role || '').trim().toLowerCase()
  if (['service_seeker', 'client', 'customer'].includes(normalized)) return '/client/security'
  if (['logistics_provider', 'transporter'].includes(normalized)) return '/transporter/security'
  if (normalized === 'everyday_user') return '/everyday/security'
  return null
}

export function StepUpProvider({ children }) {
  const location = useLocation()
  const navigate = useNavigate()
  const [challenge, setChallenge] = useState(null)
  const [setupRequired, setSetupRequired] = useState(null)
  const [mpin, setMpin] = useState('')
  const [error, setError] = useState('')
  const [pending, setPending] = useState(false)
  const resolver = useRef(null)
  const dialogRef = useRef(null)
  const mpinRef = useRef(null)
  const generation = useRef(0)

  const cancelChallenge = useCallback((message = 'Step-up authorization was cancelled.') => {
    generation.current += 1
    const current = resolver.current
    resolver.current = null
    setMpin('')
    setError('')
    setChallenge(null)
    setSetupRequired(null)
    setPending(false)
    current?.reject(new Error(message))
  }, [])

  useEffect(() => () => {
    cancelChallenge('Step-up authorization was cancelled because the page changed.')
  }, [location.key, cancelChallenge])

  useEffect(() => accessLockCoordinator.subscribe((event) => {
    if (event.type === 'access_locked' || event.type === 'full_login_required' || event.type === 'identity_context_changed') {
      cancelChallenge('Step-up authorization was cancelled because authentication changed.')
      setSetupRequired(null)
    }
  }), [cancelChallenge])

  useEffect(() => {
    if (challenge) window.requestAnimationFrame(() => mpinRef.current?.focus())
    else if (setupRequired) window.requestAnimationFrame(() => dialogRef.current?.focus())
  }, [challenge, setupRequired])

  const requestProof = useCallback((action) => new Promise((resolve, reject) => {
    if (resolver.current) {
      reject(new Error('Another protected action is awaiting MPIN authorization.'))
      return
    }
    resolver.current = { resolve, reject }
    generation.current += 1
    setChallenge(action)
    setMpin('')
    setError('')
  }), [])

  const protectedFetch = useCallback(async (url, options = {}) => {
    const first = await fetch(url, options)
    const payload = await first.clone().json().catch(() => ({}))
    if (first.status === 409 && payload?.code === 'mpin_enrollment_required') {
      const user = currentPresentedUser()
      setSetupRequired({
        action: payload?.action || null,
        path: securitySetupPathForRole(user?.role),
      })
      return first
    }
    if (first.status !== 428 || payload?.code !== 'mpin_step_up_required' || !payload?.action) return first
    const authorized = await requestProof(payload.action)
    if (authorized.generation !== generation.current) {
      throw new Error('Step-up authorization was cancelled because authentication changed.')
    }
    const headers = new Headers(options.headers || {})
    headers.set('X-MPIN-Step-Up-Proof', authorized.proof)
    return fetch(url, { ...options, headers })
  }, [requestProof])

  async function authorize(event) {
    event.preventDefault()
    if (!/^[0-9]{4}$/.test(mpin) || pending || !challenge) return
    setPending(true)
    setError('')
    const operationGeneration = generation.current
    try {
      const result = await requestJson('/auth/mpin/step-up', {
        method: 'POST',
        body: { mpin, action: challenge },
      })
      if (operationGeneration !== generation.current) return
      const current = resolver.current
      resolver.current = null
      setMpin('')
      setChallenge(null)
      current?.resolve({
        proof: result.authorization_proof,
        generation: operationGeneration,
      })
    } catch (requestError) {
      if (operationGeneration !== generation.current) return
      setMpin('')
      setError(
        requestError instanceof ApiResponseError && requestError.status === 423
          ? 'MPIN is locked. Use Security settings for recovery.'
          : requestError.message || 'MPIN authorization failed. Try again.',
      )
    } finally {
      if (operationGeneration === generation.current) setPending(false)
    }
  }

  function cancel() {
    cancelChallenge()
  }

  function closeSetupRequired() {
    setSetupRequired(null)
  }

  function goToMpinSetup() {
    if (!setupRequired?.path) {
      closeSetupRequired()
      return
    }
    setSetupRequired(null)
    navigate(setupRequired.path)
  }

  function trapFocus(event) {
    if (event.key === 'Escape') {
      event.preventDefault()
      if (!pending) cancel()
      return
    }
    if (event.key !== 'Tab') return
    const focusable = [...dialogRef.current.querySelectorAll(
      'button:not([disabled]), input:not([disabled]), [tabindex="0"]',
    )]
    if (!focusable.length) return
    const first = focusable[0]
    const last = focusable[focusable.length - 1]
    if (event.shiftKey && document.activeElement === first) {
      event.preventDefault()
      last.focus()
    } else if (!event.shiftKey && document.activeElement === last) {
      event.preventDefault()
      first.focus()
    }
  }

  return (
    <StepUpContext.Provider value={{ protectedFetch }}>
      {children}
      {setupRequired && (
        <div className="access-lock step-up-overlay" role="presentation">
          <section ref={dialogRef} className="access-lock__dialog" role="dialog" aria-modal="true" aria-labelledby="step-up-setup-title" tabIndex={-1} onKeyDown={trapFocus}>
            <div className="access-lock__icon" aria-hidden="true"><i className="fas fa-shield-halved" /></div>
            <h2 id="step-up-setup-title">MPIN setup required</h2>
            <p>
              This sensitive action requires an active MPIN. Set up an MPIN in Security settings, then retry the action.
            </p>
            {!setupRequired.path && (
              <p className="security-message is-error" role="alert">
                We could not determine the right Security page for this account. Open Security settings from your account menu.
              </p>
            )}
            <div className="access-lock__form">
              <button className="security-primary" type="button" onClick={goToMpinSetup}>
                {setupRequired.path ? 'Go to Security settings' : 'Close'}
              </button>
              {setupRequired.path && (
                <button className="security-secondary" type="button" onClick={closeSetupRequired}>Not now</button>
              )}
            </div>
          </section>
        </div>
      )}
      {challenge && (
        <div className="access-lock step-up-overlay" role="presentation">
          <section ref={dialogRef} className="access-lock__dialog" role="dialog" aria-modal="true" aria-labelledby="step-up-title" onKeyDown={trapFocus}>
            <div className="access-lock__icon" aria-hidden="true"><i className="fas fa-shield-halved" /></div>
            <h2 id="step-up-title">Authorize protected action</h2>
            <p>Enter your four digit MPIN to continue. Authorization expires in three minutes and works only for this exact action.</p>
            <form onSubmit={authorize} className="access-lock__form">
              <MpinInput ref={mpinRef} value={mpin} onChange={setMpin} disabled={pending} errorId={error ? 'step-up-error' : undefined} />
              {error && <p id="step-up-error" className="security-message is-error" role="alert">{error}</p>}
              <button className="security-primary" type="submit" disabled={pending || mpin.length !== 4}>
                {pending ? 'Authorizing…' : 'Authorize'}
              </button>
              <button className="security-secondary" type="button" onClick={cancel} disabled={pending}>Cancel</button>
            </form>
          </section>
        </div>
      )}
    </StepUpContext.Provider>
  )
}

// The provider and its hook intentionally share this one security owner.
// eslint-disable-next-line react-refresh/only-export-components
export function useStepUp() {
  const value = useContext(StepUpContext)
  if (!value) throw new Error('useStepUp must be used within StepUpProvider.')
  return value
}

import TransporterLayout from './TransporterLayout'

function toReadableLabel(value) {
  return value
    .replace(/\.html$/i, '')
    .replace(/[_-]+/g, ' ')
    .replace(/\s+/g, ' ')
    .trim()
}

function toTitleCase(value) {
  return toReadableLabel(value).replace(/\b\w/g, char => char.toUpperCase())
}

function resolveMeta(source = '') {
  if (!source) {
    return {
      folder: 'Transporter',
      title: 'Transporter',
    }
  }

  const parts = source.split('/')
  const folder = parts.length > 1 ? parts[parts.length - 2] : 'Transporter'
  const file = parts[parts.length - 1] || ''

  return {
    folder: toTitleCase(folder),
    title: toTitleCase(file),
  }
}

export function createTransporterPlaceholderPage(source) {
  function TransporterHtmlPage() {
    return <TransporterPlaceholderPage source={source} />
  }

  const meta = resolveMeta(source)
  TransporterHtmlPage.displayName = `${meta.folder}${meta.title}`.replace(/\s+/g, '')
  return TransporterHtmlPage
}

export default function TransporterPlaceholderPage({
  source = '',
  title,
  description = 'Placeholder React page created from the transporter HTML file inventory.',
  withLayout = true,
}) {
  const meta = resolveMeta(source)
  const pageTitle = title || meta.title
  const content = (
    <section className="t-page-card">
      <div className="t-page-eyebrow">{meta.folder}</div>
      <h1 className="t-page-title">{pageTitle}</h1>
      <p className="t-page-description">{description}</p>
      {source && (
        <div className="t-page-meta">
          <span>Source HTML</span>
          <code>{source}</code>
        </div>
      )}
    </section>
  )

  if (!withLayout) {
    return content
  }

  return (
    <TransporterLayout>
      {content}
    </TransporterLayout>
  )
}

