export default function AdminWithdrawals() {
  const [status, setStatus] = useState('pending')
  const [items, setItems]   = useState([])
  const [error, setError]   = useState('')

  async function load(nextStatus = status) {
    try {
      const json = await adminRequest(`/api/admin/wallet/withdrawals${qs({ status: nextStatus })}`)
      setItems(json.withdrawals || [])
    } catch (err) { setError(err.message) }
  }
  useEffect(() => { load() }, [])

  async function act(id, action) {
    if (action === 'approve' && !window.confirm('Approve this withdrawal?')) return
    try {
      await adminRequest(`/api/admin/wallet/withdrawals/${id}/${action}`, { method: 'POST', body: JSON.stringify({}) })
      load()
    } catch (err) { setError(err.message) }
  }

  return (
    <div>
      <div style={{ marginBottom: 24, display: 'flex', alignItems: 'flex-start', justifyContent: 'space-between', flexWrap: 'wrap', gap: 12 }}>
        <div>
          <h1 style={S.heading}>Wallet Withdrawals</h1>
          <p style={S.sub}>Review and process pending withdrawal requests.</p>
        </div>
        <select style={S.select} value={status} onChange={e => { setStatus(e.target.value); load(e.target.value) }}>
          <option value="">All status</option>
          <option value="pending">Pending</option>
          <option value="approved">Approved</option>
          <option value="rejected">Rejected</option>
        </select>
      </div>

      {error && <div style={S.error}><i className="fas fa-circle-exclamation" style={{ marginRight: 8 }} />{error}</div>}

      <div style={S.card}>
        <table style={{ width: '100%', borderCollapse: 'collapse' }}>
          <thead>
            <tr>{['User','Amount','Requested At','Status','Locked Balance',''].map(h => <th key={h} style={S.th}>{h}</th>)}</tr>
          </thead>
          <tbody>
            {items.map(item => (
              <tr key={item.id}
                onMouseEnter={e => e.currentTarget.style.background = '#f8fafc'}
                onMouseLeave={e => e.currentTarget.style.background = 'transparent'}
              >
                <td style={S.td}>
                  <div style={{ fontWeight: 600, color: '#0f172a' }}>{item.user_name}</div>
                  <div style={{ fontSize: 12, color: '#94a3b8' }}>{item.email}</div>
                </td>
                <td style={{ ...S.td, fontWeight: 700, color: '#0f172a' }}>{money(item.amount)}</td>
                <td style={{ ...S.td, color: '#64748b' }}>{dateText(item.requested_at)}</td>
                <td style={S.td}><span style={S.badgeStatus(item.status)}>{item.status}</span></td>
                <td style={S.td}>{money(item.current_locked_balance)}</td>
                <td style={S.td}>
                  {item.status === 'pending' && (
                    <div style={{ display: 'flex', gap: 8 }}>
                      <button onClick={() => act(item.id, 'approve')} style={S.btnGreen}>
                        <i className="fas fa-check" style={{ marginRight: 6 }} />Approve
                      </button>
                      <button onClick={() => act(item.id, 'reject')} style={S.btnRed}>
                        <i className="fas fa-times" style={{ marginRight: 6 }} />Reject
                      </button>
                    </div>
                  )}
                </td>
              </tr>
            ))}
            {items.length === 0 && (
              <tr><td colSpan={6} style={{ padding: '40px', textAlign: 'center', color: '#94a3b8', fontSize: 14 }}>No withdrawal requests found.</td></tr>
            )}
          </tbody>
        </table>
      </div>
    </div>
  )
}

import { useEffect, useState } from 'react'
import { Link } from 'react-router-dom'
import AuthCard from '../../components/common/AuthCard'
import InputField from '../../components/common/InputField'
import Notification from '../../components/common/Notification'

const STEPS = { REQUEST: 'request', VERIFY: 'verify', RESET: 'reset', DONE: 'done' }

export default function ResetPassword() {
  const [step, setStep] = useState(STEPS.REQUEST)
  const [loginId, setLoginId] = useState('')
  const [otp, setOtp] = useState('')
  const [resetToken, setResetToken] = useState('')
  const [password, setPassword] = useState('')
  const [confirmPassword, setConfirmPassword] = useState('')
  const [errors, setErrors] = useState({})
  const [loading, setLoading] = useState(false)
  const [notification, setNotification] = useState({ type: '', message: '' })
  const [maskedEmail, setMaskedEmail] = useState('')

  useEffect(() => {
    const params = new URLSearchParams(window.location.search)
    const id = params.get('loginId')
    if (id) setLoginId(id)
    const token = params.get('token')
    if (token) {
      setResetToken(token)
      setStep(STEPS.RESET)
    }
  }, [])

  async function handleRequest(event) {
    event.preventDefault()
    if (!loginId.trim()) {
      setErrors({ loginId: 'Email or CNIC is required' })
      return
    }

    setErrors({})
    setLoading(true)
    try {
      const response = await fetch('/auth/forgot-password', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        credentials: 'include',
        body: JSON.stringify({ loginId: loginId.trim() }),
      })
      const data = await response.json()
      if (response.ok && data.success) {
        setMaskedEmail(data.masked_email || '')
        setNotification({ type: 'success', message: data.message || 'OTP sent to your registered email.' })
        setStep(STEPS.VERIFY)
      } else {
        setNotification({ type: 'error', message: data.message || 'Request failed.' })
      }
    } catch (_) {
      setNotification({ type: 'error', message: 'Network error. Please try again.' })
    } finally {
      setLoading(false)
    }
  }

  async function handleVerify(event) {
    event.preventDefault()
    if (!otp.trim()) {
      setErrors({ otp: 'OTP is required' })
      return
    }

    setErrors({})
    setLoading(true)
    try {
      const response = await fetch('/auth/password-reset/verify-otp', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        credentials: 'include',
        body: JSON.stringify({ loginId: loginId.trim(), otp: otp.trim() }),
      })
      const data = await response.json()
      if (response.ok && data.success) {
        setResetToken(data.reset_token || '')
        setNotification({ type: 'success', message: 'OTP verified. Set your new password.' })
        setStep(STEPS.RESET)
      } else {
        setNotification({ type: 'error', message: data.message || 'Invalid OTP.' })
      }
    } catch (_) {
      setNotification({ type: 'error', message: 'Network error.' })
    } finally {
      setLoading(false)
    }
  }

  async function handleReset(event) {
    event.preventDefault()
    const nextErrors = {}
    if (!password) nextErrors.password = 'Password is required'
    else if (password.length < 8) nextErrors.password = 'Password must be at least 8 characters'
    if (password !== confirmPassword) nextErrors.confirmPassword = 'Passwords do not match'
    if (Object.keys(nextErrors).length) {
      setErrors(nextErrors)
      return
    }

    setErrors({})
    setLoading(true)
    try {
      const response = await fetch('/auth/reset-password', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        credentials: 'include',
        body: JSON.stringify({ reset_token: resetToken, new_password: password }),
      })
      const data = await response.json()
      if (response.ok && data.success) {
        setNotification({ type: 'success', message: 'Password reset successful.' })
        setStep(STEPS.DONE)
      } else {
        setNotification({ type: 'error', message: data.message || 'Reset failed.' })
      }
    } catch (_) {
      setNotification({ type: 'error', message: 'Network error.' })
    } finally {
      setLoading(false)
    }
  }

  const stepTitles = {
    [STEPS.REQUEST]: 'Reset your password',
    [STEPS.VERIFY]: 'Verify your email',
    [STEPS.RESET]: 'Set new password',
    [STEPS.DONE]: 'Password reset complete',
  }

  return (
    <AuthCard title={stepTitles[step]} subtitle="Account recovery">
      <Notification
        type={notification.type}
        message={notification.message}
        onClose={() => setNotification({ type: '', message: '' })}
      />

      {step === STEPS.REQUEST && (
        <form onSubmit={handleRequest}>
          <InputField
            label="Email or CNIC"
            id="loginId"
            type="text"
            placeholder="Enter your email or 13 digit CNIC"
            value={loginId}
            onChange={event => setLoginId(event.target.value)}
            error={errors.loginId}
          />
          <p className="text-gray-400 text-xs mb-5">
            DigiTransX will send a 6 digit code to the registered email linked with this account.
          </p>
          <button
            type="submit"
            disabled={loading}
            className="w-full py-3 bg-blue-500 hover:bg-blue-600 disabled:bg-gray-400 text-white font-semibold rounded-lg transition-colors flex items-center justify-center gap-2"
          >
            {loading && <span className="w-4 h-4 border-2 border-white/30 border-t-white rounded-full animate-spin" />}
            {loading ? 'Sending...' : 'Request reset'}
          </button>
          <div className="text-center mt-4">
            <Link to="/login" className="text-gray-500 text-sm hover:text-blue-500 hover:underline">Back to login</Link>
          </div>
        </form>
      )}

      {step === STEPS.VERIFY && (
        <form onSubmit={handleVerify}>
          {maskedEmail && (
            <p className="text-gray-600 text-sm mb-4">
              Enter the 6 digit code sent to <strong>{maskedEmail}</strong>
            </p>
          )}
          <InputField
            label="Verification Code"
            id="otp"
            type="text"
            placeholder="Enter 6 digit OTP"
            maxLength={6}
            value={otp}
            onChange={event => setOtp(event.target.value.replace(/\D/g, '').slice(0, 6))}
            error={errors.otp}
          />
          <button
            type="submit"
            disabled={loading}
            className="w-full py-3 bg-blue-500 hover:bg-blue-600 disabled:bg-gray-400 text-white font-semibold rounded-lg transition-colors flex items-center justify-center gap-2"
          >
            {loading && <span className="w-4 h-4 border-2 border-white/30 border-t-white rounded-full animate-spin" />}
            {loading ? 'Verifying...' : 'Verify code'}
          </button>
          <div className="text-center mt-4">
            <button
              type="button"
              onClick={() => setStep(STEPS.REQUEST)}
              className="text-gray-500 text-sm hover:text-blue-500 hover:underline bg-transparent border-none cursor-pointer"
            >
              Try a different account
            </button>
          </div>
        </form>
      )}

      {step === STEPS.RESET && (
        <form onSubmit={handleReset}>
          <InputField
            label="New Password"
            id="password"
            type="password"
            placeholder="Create a strong password"
            value={password}
            onChange={event => setPassword(event.target.value)}
            error={errors.password}
          />
          <InputField
            label="Confirm Password"
            id="confirmPassword"
            type="password"
            placeholder="Confirm your new password"
            value={confirmPassword}
            onChange={event => setConfirmPassword(event.target.value)}
            error={errors.confirmPassword}
          />
          <button
            type="submit"
            disabled={loading}
            className="w-full py-3 bg-blue-500 hover:bg-blue-600 disabled:bg-gray-400 text-white font-semibold rounded-lg transition-colors flex items-center justify-center gap-2"
          >
            {loading && <span className="w-4 h-4 border-2 border-white/30 border-t-white rounded-full animate-spin" />}
            {loading ? 'Saving...' : 'Save new password'}
          </button>
        </form>
      )}

      {step === STEPS.DONE && (
        <div className="text-center py-4">
          <div className="w-16 h-16 bg-green-100 rounded-full flex items-center justify-center mx-auto mb-4">
            <span className="text-green-500 text-3xl">OK</span>
          </div>
          <p className="text-gray-600 mb-6">Your password has been reset successfully.</p>
          <Link
            to="/login"
            className="block w-full py-3 bg-blue-500 hover:bg-blue-600 text-white font-semibold rounded-lg transition-colors text-center"
          >
            Back to Login
          </Link>
        </div>
      )}
    </AuthCard>
  )
}

import { useEffect, useMemo, useState } from 'react'
import { Link } from 'react-router-dom'
import {
  PageTitle,
  PrimaryButton,
  SectionCard,
  StateMessage,
  StatusBadge,
  apiGet,
  formatDate,
  formatMoney,
} from './clientUtils'

const activeAgreementStatuses = new Set(['accepted', 'in_progress', 'completed'])

export default function Agreements() {
  const [agreements, setAgreements] = useState([])
  const [loading, setLoading] = useState(true)
  const [error, setError] = useState('')

  async function loadAgreements() {
    setLoading(true)
    setError('')
    try {
      const json = await apiGet('/api/orders/my-orders')
      const orders = json.orders || []
      setAgreements(orders.filter((order) => activeAgreementStatuses.has(String(order.status || '').toLowerCase())))
    } catch (err) {
      setError(err.message || 'Failed to load agreement orders.')
    } finally {
      setLoading(false)
    }
  }

  useEffect(() => {
    loadAgreements()
  }, [])

  const metrics = useMemo(() => {
    const active = agreements.filter((order) => ['accepted', 'in_progress'].includes(String(order.status || '').toLowerCase())).length
    const completed = agreements.filter((order) => String(order.status || '').toLowerCase() === 'completed').length
    return [
      { label: 'Accepted Orders', value: agreements.length, icon: 'fa-file-signature', tone: 'bg-blue-50 text-blue-700' },
      { label: 'Active Agreements', value: active, icon: 'fa-check-circle', tone: 'bg-emerald-50 text-emerald-700' },
      { label: 'Completed Agreements', value: completed, icon: 'fa-clipboard-check', tone: 'bg-slate-100 text-slate-700' },
    ]
  }, [agreements])

  return (
    <>
      <PageTitle
        title="Agreements"
        subtitle="Review accepted order relationships and completed client-transporter agreements."
        actions={
          <>
            <Link to="/client/post-order" className="inline-flex min-h-10 items-center gap-2 rounded-lg bg-blue-600 px-4 py-2 text-sm font-semibold text-white hover:bg-blue-700">
              <i className="fas fa-plus" aria-hidden="true"></i> Post Order
            </Link>
            <PrimaryButton type="button" onClick={loadAgreements} disabled={loading}>
              <i className={`fas ${loading ? 'fa-spinner fa-spin' : 'fa-sync-alt'}`} aria-hidden="true"></i>
              Refresh
            </PrimaryButton>
          </>
        }
      />

      <SectionCard title="Agreement Orders Overview" icon="fa-file-contract">
        <div className="mb-5 grid grid-cols-1 gap-4 md:grid-cols-3">
          {metrics.map((metric) => (
            <article key={metric.label} className="rounded-lg border border-slate-200 bg-slate-50 p-4">
              <div className="flex items-start justify-between gap-3">
                <div>
                  <div className="text-sm font-medium text-slate-500">{metric.label}</div>
                  <div className="mt-2 text-2xl font-bold text-slate-900">{metric.value}</div>
                </div>
                <div className={`grid h-11 w-11 place-items-center rounded-lg ${metric.tone}`}>
                  <i className={`fas ${metric.icon}`} aria-hidden="true"></i>
                </div>
              </div>
            </article>
          ))}
        </div>

        {loading && <StateMessage type="loading">Loading agreement data...</StateMessage>}
        {error && <StateMessage type="error">{error}</StateMessage>}
        {!loading && !error && agreements.length === 0 && (
          <StateMessage type="empty">No accepted or completed order agreements found yet.</StateMessage>
        )}
        {!loading && !error && agreements.length > 0 && (
          <div className="overflow-x-auto">
            <table className="min-w-full divide-y divide-slate-200 text-sm">
              <thead className="bg-slate-50 text-left text-xs font-bold uppercase tracking-normal text-slate-500">
                <tr>
                  <th className="px-4 py-3">Order ID</th>
                  <th className="px-4 py-3">Pickup</th>
                  <th className="px-4 py-3">Drop</th>
                  <th className="px-4 py-3">Status</th>
                  <th className="px-4 py-3">Budget</th>
                  <th className="px-4 py-3">Date</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-slate-100 bg-white">
                {agreements.map((order) => (
                  <tr key={order.id}>
                    <td className="whitespace-nowrap px-4 py-3 font-semibold text-slate-900">{order.id}</td>
                    <td className="px-4 py-3 text-slate-600">{order.pickup_city || '-'}</td>
                    <td className="px-4 py-3 text-slate-600">{order.dropoff_city || '-'}</td>
                    <td className="px-4 py-3"><StatusBadge status={order.status} /></td>
                    <td className="px-4 py-3 text-slate-700">{formatMoney(order.estimated_budget || 0)}</td>
                    <td className="px-4 py-3 text-slate-600">{formatDate(order.created_at)}</td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        )}
      </SectionCard>
    </>
  )
}

import { useEffect, useState } from 'react'
import {
  PageTitle,
  PrimaryButton,
  SecondaryButton,
  SectionCard,
  StateMessage,
  StatusBadge,
  apiGet,
  apiSend,
  formatDate,
  formatMoney,
} from './clientUtils'

const emptyPaymentForm = {
  order_id: '',
  amount: '',
  method: 'bank_transfer',
}

export default function Balance() {
  const [balance, setBalance] = useState(null)
  const [payments, setPayments] = useState([])
  const [balanceLoading, setBalanceLoading] = useState(true)
  const [paymentsLoading, setPaymentsLoading] = useState(true)
  const [balanceError, setBalanceError] = useState('')
  const [paymentsError, setPaymentsError] = useState('')
  const [paymentModalOpen, setPaymentModalOpen] = useState(false)
  const [paymentForm, setPaymentForm] = useState(emptyPaymentForm)
  const [paymentSaving, setPaymentSaving] = useState(false)
  const [paymentError, setPaymentError] = useState('')

  async function loadBalance() {
    setBalanceLoading(true)
    setBalanceError('')
    try {
      const json = await apiGet('/api/client/balance')
      setBalance(json.balance || json.data?.balance || {})
    } catch (err) {
      setBalanceError(err.message || 'Failed to load balance.')
    } finally {
      setBalanceLoading(false)
    }
  }

  async function loadPayments() {
    setPaymentsLoading(true)
    setPaymentsError('')
    try {
      const json = await apiGet('/api/client/payments')
      setPayments(json.payments || json.data?.payments || [])
    } catch (err) {
      setPaymentsError(err.message || 'Failed to load payments.')
    } finally {
      setPaymentsLoading(false)
    }
  }

  useEffect(() => {
    loadBalance()
    loadPayments()
  }, [])

  async function submitPayment(event) {
    event.preventDefault()
    setPaymentError('')
    if (!paymentForm.order_id.trim()) {
      setPaymentError('Please enter an Order ID.')
      return
    }
    if (!paymentForm.amount || Number(paymentForm.amount) <= 0) {
      setPaymentError('Please enter a valid amount.')
      return
    }

    setPaymentSaving(true)
    try {
      await apiSend('/api/client/payments', {
        order_id: paymentForm.order_id.trim(),
        amount: Number(paymentForm.amount),
        method: paymentForm.method,
      })
      setPaymentModalOpen(false)
      setPaymentForm(emptyPaymentForm)
      await Promise.all([loadBalance(), loadPayments()])
    } catch (err) {
      setPaymentError(err.message || 'Payment failed.')
    } finally {
      setPaymentSaving(false)
    }
  }

  return (
    <>
      <PageTitle title="Balance & Payments" subtitle="Manage your wallet balance and view payment history." />

      <SectionCard
        title="Balance Summary"
        actions={
          <>
            <SecondaryButton type="button" onClick={loadBalance} disabled={balanceLoading}>
              <i className={`fas ${balanceLoading ? 'fa-spinner fa-spin' : 'fa-sync-alt'}`} aria-hidden="true"></i>
              Refresh
            </SecondaryButton>
            <PrimaryButton type="button" onClick={() => setPaymentModalOpen(true)}>
              <i className="fas fa-credit-card" aria-hidden="true"></i>
              Make Payment
            </PrimaryButton>
          </>
        }
      >
        {balanceLoading && <StateMessage type="loading">Loading balance...</StateMessage>}
        {balanceError && <StateMessage type="error">{balanceError}</StateMessage>}
        {!balanceLoading && !balanceError && (
          <div className="grid grid-cols-1 gap-4 md:grid-cols-3">
            <article className="rounded-lg border border-slate-200 bg-slate-50 p-4">
              <div className="grid h-11 w-11 place-items-center rounded-lg bg-blue-50 text-blue-700">
                <i className="fas fa-wallet" aria-hidden="true"></i>
              </div>
              <div className="mt-3 text-sm font-medium text-slate-500">Wallet Balance</div>
              <div className="mt-1 text-2xl font-bold text-slate-900">{formatMoney(balance?.balance ?? 0)}</div>
              <div className="mt-1 text-xs text-slate-500">Available for withdrawals</div>
            </article>
            <article className="rounded-lg border border-slate-200 bg-slate-50 p-4">
              <div className="grid h-11 w-11 place-items-center rounded-lg bg-emerald-50 text-emerald-700">
                <i className="fas fa-receipt" aria-hidden="true"></i>
              </div>
              <div className="mt-3 text-sm font-medium text-slate-500">Total Payments</div>
              <div className="mt-1 text-2xl font-bold text-slate-900">{payments.length}</div>
              <div className="mt-1 text-xs text-slate-500">Successful transactions</div>
            </article>
            <article className="rounded-lg border border-slate-200 bg-slate-50 p-4">
              <div className="grid h-11 w-11 place-items-center rounded-lg bg-amber-50 text-amber-700">
                <i className="fas fa-clock" aria-hidden="true"></i>
              </div>
              <div className="mt-3 text-sm font-medium text-slate-500">Last Payment</div>
              <div className="mt-1 text-2xl font-bold text-slate-900">{formatDate(payments[0]?.created_at)}</div>
              <div className="mt-1 text-xs text-slate-500">Most recent transaction</div>
            </article>
          </div>
        )}
      </SectionCard>

      <SectionCard
        title="Payment History"
        actions={
          <SecondaryButton type="button" onClick={loadPayments} disabled={paymentsLoading}>
            <i className={`fas ${paymentsLoading ? 'fa-spinner fa-spin' : 'fa-sync-alt'}`} aria-hidden="true"></i>
            Refresh
          </SecondaryButton>
        }
      >
        {paymentsLoading && <StateMessage type="loading">Loading payments...</StateMessage>}
        {paymentsError && <StateMessage type="error">{paymentsError}</StateMessage>}
        {!paymentsLoading && !paymentsError && payments.length === 0 && (
          <StateMessage type="empty">No payments found.</StateMessage>
        )}
        {!paymentsLoading && !paymentsError && payments.length > 0 && (
          <div className="overflow-x-auto">
            <table className="min-w-full divide-y divide-slate-200 text-sm">
              <thead className="bg-slate-50 text-left text-xs font-bold uppercase tracking-normal text-slate-500">
                <tr>
                  <th className="px-4 py-3">Payment ID</th>
                  <th className="px-4 py-3">Order ID</th>
                  <th className="px-4 py-3">Amount</th>
                  <th className="px-4 py-3">Method</th>
                  <th className="px-4 py-3">Status</th>
                  <th className="px-4 py-3">Date</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-slate-100 bg-white">
                {payments.map((payment) => (
                  <tr key={payment.payment_id || payment.id}>
                    <td className="whitespace-nowrap px-4 py-3 font-semibold text-slate-900">{payment.payment_id || payment.payment_code || payment.id || '-'}</td>
                    <td className="px-4 py-3 text-slate-600">{payment.order_id || '-'}</td>
                    <td className="px-4 py-3 text-slate-700">{formatMoney(payment.amount)}</td>
                    <td className="px-4 py-3 capitalize text-slate-600">{String(payment.payment_method || payment.method || '-').replace(/_/g, ' ')}</td>
                    <td className="px-4 py-3"><StatusBadge status={payment.status} /></td>
                    <td className="px-4 py-3 text-slate-600">{formatDate(payment.created_at)}</td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        )}
      </SectionCard>

      {paymentModalOpen && (
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-slate-900/50 px-4" onClick={() => setPaymentModalOpen(false)}>
          <form className="w-full max-w-md rounded-lg bg-white p-5 shadow-xl" onClick={(event) => event.stopPropagation()} onSubmit={submitPayment}>
            <h3 className="text-lg font-bold text-slate-900">Make Payment</h3>
            <div className="mt-4 space-y-4">
              <label className="block">
                <span className="text-sm font-semibold text-slate-700">Order ID</span>
                <input
                  value={paymentForm.order_id}
                  onChange={(event) => setPaymentForm((form) => ({ ...form, order_id: event.target.value }))}
                  className="mt-1 h-10 w-full rounded-lg border border-slate-300 px-3 text-sm outline-none focus:border-blue-500 focus:ring-2 focus:ring-blue-100"
                  placeholder="Enter order ID from current orders"
                />
              </label>
              <label className="block">
                <span className="text-sm font-semibold text-slate-700">Amount (PKR)</span>
                <input
                  type="number"
                  min="1"
                  step="0.01"
                  value={paymentForm.amount}
                  onChange={(event) => setPaymentForm((form) => ({ ...form, amount: event.target.value }))}
                  className="mt-1 h-10 w-full rounded-lg border border-slate-300 px-3 text-sm outline-none focus:border-blue-500 focus:ring-2 focus:ring-blue-100"
                  placeholder="Enter amount"
                />
              </label>
              <label className="block">
                <span className="text-sm font-semibold text-slate-700">Payment Method</span>
                <select
                  value={paymentForm.method}
                  onChange={(event) => setPaymentForm((form) => ({ ...form, method: event.target.value }))}
                  className="mt-1 h-10 w-full rounded-lg border border-slate-300 bg-white px-3 text-sm outline-none focus:border-blue-500 focus:ring-2 focus:ring-blue-100"
                >
                  <option value="bank_transfer">Bank Transfer</option>
                  <option value="card">Credit/Debit Card</option>
                  <option value="wallet">Wallet Balance</option>
                  <option value="easypaisa">EasyPaisa</option>
                  <option value="jazzcash">JazzCash</option>
                </select>
              </label>
            </div>
            {paymentError && <div className="mt-3 text-sm text-red-600">{paymentError}</div>}
            <div className="mt-5 flex gap-2">
              <SecondaryButton type="button" onClick={() => setPaymentModalOpen(false)} className="flex-1">
                Cancel
              </SecondaryButton>
              <PrimaryButton type="submit" disabled={paymentSaving} className="flex-1">
                <i className={`fas ${paymentSaving ? 'fa-spinner fa-spin' : 'fa-credit-card'}`} aria-hidden="true"></i>
                Submit
              </PrimaryButton>
            </div>
          </form>
        </div>
      )}
    </>
  )
}

import { useEffect, useState } from 'react'
import { Link } from 'react-router-dom'
import {
  PageTitle,
  StateMessage,
  StatusBadge,
  apiGet,
  formatMoney,
  isActiveStatus,
  isCompletedStatus,
} from './clientUtils'

const initialStats = {
  walletBalance: 0,
  totalOrders: 0,
  activeOrders: 0,
  completedOrders: 0,
}

const QUICK_ACTIONS = [
  { to: '/client/post-order', icon: 'fa-shipping-fast', title: 'Post Order', subtitle: 'Request a new shipment' },
  { to: '/client/orders', icon: 'fa-clipboard-list', title: 'My Orders', subtitle: 'Track requests and bids' },
  { to: '/client/post-agreement', icon: 'fa-file-circle-plus', title: 'Post Agreement', subtitle: 'Set up a recurring contract' },
  { to: '/client/wallet', icon: 'fa-wallet', title: 'Wallet', subtitle: 'Top up and view balance' },
  { to: '/client/messages', icon: 'fa-comments', title: 'Messages', subtitle: 'Chat with transporters' },
]

export default function ClientDashboard() {
  const [stats, setStats] = useState(initialStats)
  const [orders, setOrders] = useState([])
  const [loading, setLoading] = useState(true)
  const [ordersLoading, setOrdersLoading] = useState(false)
  const [error, setError] = useState('')

  async function loadDashboard() {
    setLoading(true)
    setError('')
    try {
      const [ordersJson, walletJson] = await Promise.all([
        apiGet('/api/orders/my-orders'),
        apiGet('/api/wallet').catch(() => ({ wallet: {} })),
      ])
      const myOrders = ordersJson.orders || []
      const wallet = walletJson.wallet || {}
      setStats({
        walletBalance: wallet.balance ?? 0,
        totalOrders: myOrders.length,
        activeOrders: myOrders.filter((order) => isActiveStatus(order.status)).length,
        completedOrders: myOrders.filter((order) => isCompletedStatus(order.status)).length,
      })
      setOrders(myOrders.slice(0, 6))
    } catch (err) {
      setError(err.message || 'Failed to load dashboard.')
    } finally {
      setLoading(false)
    }
  }

  async function refreshOrders() {
    setOrdersLoading(true)
    try {
      const json = await apiGet('/api/orders/my-orders')
      setOrders((json.orders || []).slice(0, 6))
    } catch (_) {
      /* keep existing list on refresh error */
    } finally {
      setOrdersLoading(false)
    }
  }

  useEffect(() => {
    loadDashboard()
  }, [])

  const statCards = [
    { label: 'Wallet Balance', value: formatMoney(stats.walletBalance), icon: 'fa-wallet', variant: 'wallet' },
    { label: 'Total Orders', value: stats.totalOrders, icon: 'fa-receipt', variant: 'orders' },
    { label: 'Active Orders', value: stats.activeOrders, icon: 'fa-spinner', variant: 'active' },
    { label: 'Completed Orders', value: stats.completedOrders, icon: 'fa-circle-check', variant: 'completed' },
  ]

  return (
    <>
      <PageTitle
        title="Service Seeker Dashboard"
        subtitle="Track your shipment requests, compare bids, and keep an eye on your wallet balance."
      />

      {error && <StateMessage type="error">{error}</StateMessage>}

      <div className="dashboard-kpi-grid">
        {statCards.map((card) => (
          <article key={card.label} className="dashboard-stat-card">
            <div className="dashboard-stat-card__header">
              <div>
                <div className="dashboard-card-title">{card.label}</div>
                <div className="dashboard-card-value">
                  {loading ? <i className="fas fa-spinner fa-spin" aria-hidden="true"></i> : card.value}
                </div>
              </div>
              <div className={`dashboard-card-icon dashboard-card-icon--${card.variant}`}>
                <i className={`fas ${card.icon}`} aria-hidden="true"></i>
              </div>
            </div>
          </article>
        ))}
      </div>

      <section className="dashboard-section">
        <h2 className="dashboard-section-title">Quick Actions</h2>
        <div className="dashboard-actions-grid">
          {QUICK_ACTIONS.map((action) => (
            <Link key={action.to} to={action.to} className="dashboard-action-tile">
              <div className="dashboard-action-tile__icon">
                <i className={`fas ${action.icon}`} aria-hidden="true"></i>
              </div>
              <span>{action.title}</span>
              <div>{action.subtitle}</div>
            </Link>
          ))}
        </div>
      </section>

      <section className="dashboard-section">
        <div
          style={{
            display: 'flex',
            justifyContent: 'space-between',
            alignItems: 'center',
            flexWrap: 'wrap',
            gap: 12,
            marginBottom: 22,
          }}
        >
          <h2 className="dashboard-section-title" style={{ marginBottom: 0 }}>
            Recent Shipment Requests
          </h2>
          <button
            type="button"
            className="dashboard-action-small client-btn-ghost"
            onClick={refreshOrders}
            disabled={ordersLoading || loading}
          >
            <i className={`fas ${ordersLoading ? 'fa-spinner fa-spin' : 'fa-sync-alt'}`} aria-hidden="true"></i>
            Refresh
          </button>
        </div>

        {loading ? (
          <p className="dashboard-loading">
            <i className="fas fa-spinner fa-spin" aria-hidden="true"></i> Loading recent requests...
          </p>
        ) : orders.length === 0 ? (
          <div className="dashboard-empty-state">
            <i className="fas fa-box-open" aria-hidden="true"></i>
            <p>
              No shipment requests yet. <Link to="/client/post-order">Post your first order</Link>
            </p>
          </div>
        ) : (
          <div className="client-order-grid">
            {orders.map((order) => (
              <article key={order.id} className="client-order-card">
                <div className="client-order-card__top">
                  <div>
                    <div className="client-order-card__route">
                      {order.pickup_city || 'Pickup'}
                      <i className="fas fa-arrow-right" aria-hidden="true"></i>
                      {order.dropoff_city || 'Dropoff'}
                    </div>
                    <div className="client-order-card__meta">
                      Order #{order.id} &middot; {order.goods_type || 'General goods'}
                    </div>
                  </div>
                  <StatusBadge status={order.status} />
                </div>
                <div className="client-order-card__stats">
                  <div>
                    <div className="client-order-card__budget-label">Budget</div>
                    <div className="client-order-card__budget-value">
                      {order.estimated_budget ? formatMoney(order.estimated_budget) : '—'}
                    </div>
                  </div>
                  <Link to={`/client/order/${order.id}`} className="dashboard-action-small">
                    View
                  </Link>
                </div>
              </article>
            ))}
          </div>
        )}
      </section>
    </>
  )
}

import { useEffect, useRef, useState } from 'react'
import { apiGet, apiSend } from '../client/clientUtils'

export default function DriverActiveTrip() {
  const [profile, setProfile] = useState(null)
  const [tracking, setTracking] = useState(false)
  const [lastCoords, setLastCoords] = useState(null)
  const [pingsCount, setPingsCount] = useState(0)
  const [error, setError] = useState('')
  const [statusMsg, setStatusMsg] = useState('')
  const watchIdRef = useRef(null)

  useEffect(() => {
    apiGet('/api/driver/me')
      .then((res) => {
        if (res.success) setProfile(res.driver)
      })
      .catch((err) => setError(err.message))

    return () => {
      if (watchIdRef.current) {
        navigator.geolocation.clearWatch(watchIdRef.current)
      }
    }
  }, [])

  function sendPing(position) {
    const lat = position.coords.latitude
    const lng = position.coords.longitude
    const speed = position.coords.speed ? (position.coords.speed * 3.6).toFixed(1) : 0
    const heading = position.coords.heading || 0
    const altitude = position.coords.altitude || null

    setLastCoords({ lat, lng, speed, heading, time: new Date().toLocaleTimeString() })

    apiSend('/api/driver/gps/ping', {
      lat,
      lng,
      speed_kmh: speed,
      heading,
      altitude,
    })
      .then(() => {
        setPingsCount((c) => c + 1)
        setStatusMsg('Live location streamed to software successfully.')
      })
      .catch((err) => {
        setStatusMsg(`Ping warning: ${err.message}`)
      })
  }

  function startStreaming() {
    if (!navigator.geolocation) {
      setError('Geolocation is not supported by your browser/device.')
      return
    }

    setError('')
    setStatusMsg('Acquiring GPS fix...')
    setTracking(true)

    // Send first fix immediately
    navigator.geolocation.getCurrentPosition(sendPing, (err) => {
      setError(`GPS Error: ${err.message}`)
    })

    // Watch position in real time
    watchIdRef.current = navigator.geolocation.watchPosition(
      sendPing,
      (err) => setError(`GPS Error: ${err.message}`),
      {
        enableHighAccuracy: true,
        timeout: 10000,
        maximumAge: 0,
      }
    )
  }

  function stopStreaming() {
    if (watchIdRef.current) {
      navigator.geolocation.clearWatch(watchIdRef.current)
      watchIdRef.current = null
    }
    setTracking(false)
    setStatusMsg('GPS streaming paused.')
  }

  return (
    <div>
      <div className="driver-card">
        <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', flexWrap: 'wrap', gap: '16px' }}>
          <div>
            <h1 style={{ margin: 0, fontSize: '1.6rem', fontWeight: 800 }}>Live GPS Trip Console</h1>
            <p style={{ margin: '4px 0 0 0', color: '#64748b' }}>
              Stream your smartphone's real-time GPS location directly to the Transporter &amp; Customer tracking map.
            </p>
          </div>

          <div>
            {tracking ? (
              <button
                type="button"
                onClick={stopStreaming}
                style={{
                  background: '#ef4444',
                  color: 'white',
                  border: 'none',
                  padding: '12px 24px',
                  borderRadius: '8px',
                  fontWeight: 700,
                  fontSize: '1rem',
                  cursor: 'pointer',
                  display: 'flex',
                  alignItems: 'center',
                  gap: '8px',
                }}
              >
                <i className="fas fa-pause"></i> Stop GPS Streaming
              </button>
            ) : (
              <button
                type="button"
                onClick={startStreaming}
                style={{
                  background: '#16a34a',
                  color: 'white',
                  border: 'none',
                  padding: '12px 24px',
                  borderRadius: '8px',
                  fontWeight: 700,
                  fontSize: '1rem',
                  cursor: 'pointer',
                  display: 'flex',
                  alignItems: 'center',
                  gap: '8px',
                }}
              >
                <i className="fas fa-satellite-dish"></i> Start Live GPS Broadcast
              </button>
            )}
          </div>
        </div>

        {error && (
          <div style={{ marginTop: '16px', padding: '12px', background: '#fef2f2', border: '1px solid #fecaca', borderRadius: '8px', color: '#b91c1c' }}>
            {error}
          </div>
        )}

        <div style={{ marginTop: '24px', padding: '20px', background: tracking ? '#f0fdf4' : '#f8fafc', border: `1px solid ${tracking ? '#bbf7d0' : '#e2e8f0'}`, borderRadius: '12px' }}>
          <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
            <div className="gps-live-indicator">
              <span className="gps-pulse-dot" style={{ background: tracking ? '#16a34a' : '#94a3b8' }}></span>
              <span>{tracking ? 'GPS BROADCAST ACTIVE' : 'BROADCAST STANDBY'}</span>
            </div>
            <span style={{ fontSize: '0.85rem', color: '#64748b' }}>Total Pings Sent: <strong>{pingsCount}</strong></span>
          </div>

          {lastCoords ? (
            <div style={{ marginTop: '16px', display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(140px, 1fr))', gap: '12px' }}>
              <div style={{ background: 'white', padding: '10px 14px', borderRadius: '8px', border: '1px solid #e2e8f0' }}>
                <span style={{ fontSize: '0.75rem', color: '#64748b' }}>LATITUDE</span>
                <p style={{ margin: '2px 0 0 0', fontWeight: 700 }}>{lastCoords.lat.toFixed(6)}</p>
              </div>
              <div style={{ background: 'white', padding: '10px 14px', borderRadius: '8px', border: '1px solid #e2e8f0' }}>
                <span style={{ fontSize: '0.75rem', color: '#64748b' }}>LONGITUDE</span>
                <p style={{ margin: '2px 0 0 0', fontWeight: 700 }}>{lastCoords.lng.toFixed(6)}</p>
              </div>
              <div style={{ background: 'white', padding: '10px 14px', borderRadius: '8px', border: '1px solid #e2e8f0' }}>
                <span style={{ fontSize: '0.75rem', color: '#64748b' }}>SPEED</span>
                <p style={{ margin: '2px 0 0 0', fontWeight: 700 }}>{lastCoords.speed} km/h</p>
              </div>
              <div style={{ background: 'white', padding: '10px 14px', borderRadius: '8px', border: '1px solid #e2e8f0' }}>
                <span style={{ fontSize: '0.75rem', color: '#64748b' }}>LAST SYNC</span>
                <p style={{ margin: '2px 0 0 0', fontWeight: 700 }}>{lastCoords.time}</p>
              </div>
            </div>
          ) : (
            <p style={{ marginTop: '12px', color: '#64748b', fontSize: '0.9rem' }}>
              Press &quot;Start Live GPS Broadcast&quot; when beginning your journey. Ensure your phone allows location access.
            </p>
          )}

          {statusMsg && (
            <p style={{ margin: '14px 0 0 0', fontSize: '0.85rem', color: '#16a34a', fontWeight: 600 }}>
              <i className="fas fa-check-circle"></i> {statusMsg}
            </p>
          )}
        </div>
      </div>
    </div>
  )
}

import { useEffect, useState } from 'react'
import { apiGet, apiSend, formatMoney } from '../client/clientUtils'

const POPULAR_BRANDS = ['PSO', 'Shell', 'TotalParco', 'Attock Petroleum', 'Hascol', 'Gas & Go', 'Other']

export default function DriverFuelLogs() {
  const [logs, setLogs] = useState([])
  const [stats, setStats] = useState(null)
  const [trips, setTrips] = useState([])
  const [loading, setLoading] = useState(true)
  const [submitting, setSubmitting] = useState(false)
  const [showAddModal, setShowAddModal] = useState(false)
  const [msg, setMsg] = useState('')
  const [error, setError] = useState('')

  // Form State
  const [pumpName, setPumpName] = useState('')
  const [pumpBrand, setPumpBrand] = useState('PSO')
  const [city, setCity] = useState('')
  const [areaLandmark, setAreaLandmark] = useState('')
  const [fuelType, setFuelType] = useState('diesel')
  const [liters, setLiters] = useState('')
  const [pricePerLiter, setPricePerLiter] = useState('285')
  const [paymentMode, setPaymentMode] = useState('cash')
  const [selectedAssignmentId, setSelectedAssignmentId] = useState('')
  const [tripDistanceKm, setTripDistanceKm] = useState('')
  const [odometerKm, setOdometerKm] = useState('')
  const [fuelDate, setFuelDate] = useState(() => new Date().toISOString().split('T')[0])
  const [notes, setNotes] = useState('')

  function loadData() {
    setLoading(true)
    Promise.all([
      apiGet('/api/driver/fuel-logs'),
      apiGet('/api/driver/trips-for-fuel'),
    ])
      .then(([logsRes, tripsRes]) => {
        if (logsRes.success) {
          setLogs(logsRes.logs || [])
          setStats(logsRes.stats || null)
        }
        if (tripsRes.success) {
          setTrips(tripsRes.trips || [])
        }
      })
      .catch((err) => setError(err.message || 'Failed to load fuel records.'))
      .finally(() => setLoading(false))
  }

  useEffect(() => {
    loadData()
  }, [])

  function handleTripSelect(e) {
    const asgnId = e.target.value
    setSelectedAssignmentId(asgnId)
    if (!asgnId) {
      setTripDistanceKm('')
      return
    }
    const chosen = trips.find((t) => String(t.assignment_id) === String(asgnId))
    if (chosen && chosen.actual_distance_km) {
      setTripDistanceKm(String(chosen.actual_distance_km))
    }
  }

  // Auto-calculated fields
  const calculatedTotal = Number(liters || 0) * Number(pricePerLiter || 0)
  const calculatedAvg = Number(tripDistanceKm) > 0 && Number(liters) > 0
    ? (Number(tripDistanceKm) / Number(liters)).toFixed(2)
    : null

  async function handleSubmit(e) {
    e.preventDefault()
    if (!pumpName.trim() || !city.trim() || Number(liters) <= 0 || Number(pricePerLiter) <= 0) {
      setError('Please fill in pump name, city, liters, and price.')
      return
    }

    setSubmitting(true)
    setError('')
    setMsg('')

    try {
      const payload = {
        pump_name: pumpName.trim(),
        pump_brand: pumpBrand,
        city: city.trim(),
        area_landmark: areaLandmark.trim(),
        fuel_type: fuelType,
        liters: Number(liters),
        price_per_liter: Number(pricePerLiter),
        payment_mode: paymentMode,
        assignment_id: selectedAssignmentId ? Number(selectedAssignmentId) : null,
        trip_distance_km: tripDistanceKm ? Number(tripDistanceKm) : null,
        odometer_km: odometerKm ? Number(odometerKm) : null,
        fuel_date: fuelDate,
        notes: notes.trim(),
      }

      const res = await apiSend('/api/driver/fuel-logs', payload)
      if (res.success) {
        setMsg(res.message || 'Fuel record added successfully!')
        setShowAddModal(false)
        // Reset form
        setPumpName('')
        setAreaLandmark('')
        setLiters('')
        setNotes('')
        loadData()
      } else {
        setError(res.message || 'Failed to add log.')
      }
    } catch (err) {
      setError(err.message || 'Network error.')
    } finally {
      setSubmitting(false)
    }
  }

  return (
    <div>
      <div className="driver-card">
        <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', flexWrap: 'wrap', gap: '16px' }}>
          <div>
            <h1 style={{ margin: 0, fontSize: '1.6rem', fontWeight: 800 }}>Fuel &amp; Diesel Consumption Log</h1>
            <p style={{ margin: '4px 0 0 0', color: '#64748b' }}>
              Track every cash or card refuel with exact pump station name, city, area location, and trip fuel average.
            </p>
          </div>

          <button
            type="button"
            onClick={() => { setShowAddModal(true); setError(''); setMsg(''); }}
            style={{
              background: '#2563eb',
              color: 'white',
              border: 'none',
              padding: '12px 20px',
              borderRadius: '8px',
              fontWeight: 700,
              fontSize: '0.95rem',
              cursor: 'pointer',
              display: 'flex',
              alignItems: 'center',
              gap: '8px',
            }}
          >
            <i className="fas fa-gas-pump"></i> Record New Refuel
          </button>
        </div>

        {/* Stats Overview */}
        {stats && (
          <div className="driver-stat-grid" style={{ marginTop: '20px' }}>
            <div className="driver-stat-box">
              <p>Total Fuel Expense</p>
              <h3 style={{ color: '#0f172a' }}>{formatMoney(stats.total_fuel_spent)}</h3>
              <small style={{ color: '#64748b' }}>Across all trips</small>
            </div>
            <div className="driver-stat-box">
              <p>Total Diesel / Fuel</p>
              <h3 style={{ color: '#2563eb' }}>{stats.total_liters} Liters</h3>
              <small style={{ color: '#64748b' }}>{stats.total_refuels} Refuel visits</small>
            </div>
            <div className="driver-stat-box">
              <p>Average Mileage</p>
              <h3 style={{ color: Number(stats.avg_km_per_liter) >= 4.0 ? '#16a34a' : '#ea580c' }}>
                {stats.avg_km_per_liter > 0 ? `${stats.avg_km_per_liter} km/L` : '—'}
              </h3>
              <small style={{ color: '#64748b' }}>Trip distance &divide; consumed liters</small>
            </div>
          </div>
        )}

        {msg && (
          <div style={{ marginTop: '16px', padding: '12px', background: '#f0fdf4', color: '#166534', border: '1px solid #bbf7d0', borderRadius: '8px' }}>
            <i className="fas fa-check-circle" style={{ marginRight: '6px' }}></i> {msg}
          </div>
        )}
      </div>

      {/* Fuel Logs Table / Cards */}
      <div className="driver-card">
        <h2 style={{ fontSize: '1.25rem', fontWeight: 700, margin: '0 0 16px 0' }}>Refuel History &amp; Consumption Records</h2>

        {loading ? (
          <p>Loading fuel records...</p>
        ) : logs.length === 0 ? (
          <div style={{ textAlign: 'center', padding: '30px', color: '#64748b', background: '#f8fafc', borderRadius: '8px', border: '1px dashed #cbd5e1' }}>
            <i className="fas fa-gas-pump" style={{ fontSize: '2.5rem', color: '#94a3b8', marginBottom: '8px' }}></i>
            <p style={{ margin: 0, fontWeight: 700 }}>No fuel entries recorded yet.</p>
            <p style={{ margin: '4px 0 0 0', fontSize: '0.85rem' }}>Click &quot;Record New Refuel&quot; whenever you fill diesel or petrol during your journey.</p>
          </div>
        ) : (
          <div style={{ overflowX: 'auto' }}>
            <table style={{ width: '100%', borderCollapse: 'collapse', textAlign: 'left', fontSize: '0.9rem' }}>
              <thead>
                <tr style={{ borderBottom: '2px solid #e2e8f0', color: '#475569' }}>
                  <th style={{ padding: '10px 12px' }}>Date</th>
                  <th style={{ padding: '10px 12px' }}>Pump &amp; Exact Location</th>
                  <th style={{ padding: '10px 12px' }}>Trip / Route</th>
                  <th style={{ padding: '10px 12px' }}>Fuel Type &amp; Liters</th>
                  <th style={{ padding: '10px 12px' }}>Rate &amp; Total Paid</th>
                  <th style={{ padding: '10px 12px' }}>Trip Avg (km/L)</th>
                  <th style={{ padding: '10px 12px' }}>Payment</th>
                </tr>
              </thead>
              <tbody>
                {logs.map((log) => (
                  <tr key={log.id} style={{ borderBottom: '1px solid #f1f5f9' }}>
                    <td style={{ padding: '12px', whiteSpace: 'nowrap', fontWeight: 600 }}>{log.fuel_date}</td>
                    <td style={{ padding: '12px' }}>
                      <div style={{ fontWeight: 700, color: '#0f172a' }}>
                        {log.pump_brand ? `[${log.pump_brand}] ` : ''}{log.pump_name}
                      </div>
                      <div style={{ fontSize: '0.8rem', color: '#64748b', display: 'flex', alignItems: 'center', gap: '4px', marginTop: '2px' }}>
                        <i className="fas fa-location-dot" style={{ color: '#ef4444' }}></i>
                        {log.area_landmark ? `${log.area_landmark}, ` : ''}{log.city}
                      </div>
                    </td>
                    <td style={{ padding: '12px' }}>
                      {log.pickup_city && log.dropoff_city ? (
                        <div>
                          <span style={{ fontWeight: 600, color: '#1e293b' }}>{log.pickup_city} &rarr; {log.dropoff_city}</span>
                          {log.trip_distance_km && (
                            <span style={{ display: 'block', fontSize: '0.75rem', color: '#64748b' }}>
                              Dist: {log.trip_distance_km} km
                            </span>
                          )}
                        </div>
                      ) : (
                        <span style={{ color: '#94a3b8' }}>General / Standby</span>
                      )}
                    </td>
                    <td style={{ padding: '12px' }}>
                      <strong style={{ textTransform: 'capitalize' }}>{log.fuel_type}</strong>
                      <div style={{ color: '#2563eb', fontWeight: 700 }}>{log.liters} Liters</div>
                    </td>
                    <td style={{ padding: '12px' }}>
                      <div style={{ fontWeight: 800, color: '#0f172a' }}>{formatMoney(log.total_amount)}</div>
                      <small style={{ color: '#64748b' }}>@{formatMoney(log.price_per_liter)}/L</small>
                    </td>
                    <td style={{ padding: '12px' }}>
                      {log.fuel_average_km_per_liter ? (
                        <span style={{
                          padding: '3px 8px',
                          borderRadius: '6px',
                          fontSize: '0.8rem',
                          fontWeight: 700,
                          background: Number(log.fuel_average_km_per_liter) >= 4.0 ? '#dcfce7' : '#ffedd5',
                          color: Number(log.fuel_average_km_per_liter) >= 4.0 ? '#166534' : '#9a3412',
                        }}>
                          {log.fuel_average_km_per_liter} km/L
                        </span>
                      ) : (
                        <span style={{ color: '#94a3b8' }}>—</span>
                      )}
                    </td>
                    <td style={{ padding: '12px' }}>
                      <span style={{
                        textTransform: 'uppercase',
                        fontSize: '0.75rem',
                        fontWeight: 700,
                        background: '#f1f5f9',
                        padding: '3px 8px',
                        borderRadius: '4px',
                        color: '#475569',
                      }}>
                        {log.payment_mode}
                      </span>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        )}
      </div>

      {/* Add Fuel Modal */}
      {showAddModal && (
        <div style={{
          position: 'fixed',
          top: 0,
          left: 0,
          right: 0,
          bottom: 0,
          backgroundColor: 'rgba(0,0,0,0.5)',
          display: 'flex',
          alignItems: 'center',
          justifyContent: 'center',
          zIndex: 1000,
          padding: '20px',
        }}>
          <div style={{
            background: 'white',
            borderRadius: '12px',
            maxWidth: '650px',
            width: '100%',
            maxHeight: '90vh',
            overflowY: 'auto',
            padding: '24px',
            boxShadow: '0 20px 25px -5px rgba(0,0,0,0.2)',
          }}>
            <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', borderBottom: '1px solid #e2e8f0', paddingBottom: '12px' }}>
              <div style={{ display: 'flex', alignItems: 'center', gap: '8px' }}>
                <i className="fas fa-gas-pump" style={{ fontSize: '1.25rem', color: '#2563eb' }}></i>
                <h2 style={{ margin: 0, fontSize: '1.3rem', fontWeight: 800 }}>Record Fuel Refuel</h2>
              </div>
              <button
                type="button"
                onClick={() => setShowAddModal(false)}
                style={{ background: 'none', border: 'none', fontSize: '1.25rem', cursor: 'pointer', color: '#64748b' }}
              >
                &times;
              </button>
            </div>

            {error && (
              <div style={{ marginTop: '12px', padding: '10px', background: '#fef2f2', border: '1px solid #fecaca', borderRadius: '6px', color: '#b91c1c', fontSize: '0.85rem' }}>
                {error}
              </div>
            )}

            <form onSubmit={handleSubmit} style={{ marginTop: '16px', display: 'flex', flexDirection: 'column', gap: '14px' }}>
              {/* Trip Selection */}
              <div>
                <label style={{ display: 'block', fontSize: '0.85rem', fontWeight: 700, color: '#334155', marginBottom: '4px' }}>
                  Select Related Trip (For Distance &amp; Mileage Calculation)
                </label>
                <select
                  value={selectedAssignmentId}
                  onChange={handleTripSelect}
                  style={{ width: '100%', padding: '10px 12px', borderRadius: '8px', border: '1px solid #cbd5e1' }}
                >
                  <option value="">No specific trip (General fleet / Standby refill)</option>
                  {trips.map((t) => (
                    <option key={t.assignment_id} value={t.assignment_id}>
                      Truck {t.truck_number}: {t.pickup_city || 'City'} &rarr; {t.dropoff_city || 'City'} {t.actual_distance_km ? `(${t.actual_distance_km} km)` : ''}
                    </option>
                  ))}
                </select>
              </div>

              {/* Pump Details */}
              <div style={{ display: 'grid', gridTemplateColumns: '1fr 2fr', gap: '10px' }}>
                <div>
                  <label style={{ display: 'block', fontSize: '0.85rem', fontWeight: 700, color: '#334155', marginBottom: '4px' }}>
                    Brand
                  </label>
                  <select
                    value={pumpBrand}
                    onChange={(e) => setPumpBrand(e.target.value)}
                    style={{ width: '100%', padding: '10px 12px', borderRadius: '8px', border: '1px solid #cbd5e1' }}
                  >
                    {POPULAR_BRANDS.map((b) => (
                      <option key={b} value={b}>{b}</option>
                    ))}
                  </select>
                </div>
                <div>
                  <label style={{ display: 'block', fontSize: '0.85rem', fontWeight: 700, color: '#334155', marginBottom: '4px' }}>
                    Pump / Station Name *
                  </label>
                  <input
                    type="text"
                    required
                    placeholder="e.g. PSO Al-Rehman Petroleum"
                    value={pumpName}
                    onChange={(e) => setPumpName(e.target.value)}
                    style={{ width: '100%', padding: '10px 12px', borderRadius: '8px', border: '1px solid #cbd5e1' }}
                  />
                </div>
              </div>

              {/* Exact Location & Area */}
              <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '10px' }}>
                <div>
                  <label style={{ display: 'block', fontSize: '0.85rem', fontWeight: 700, color: '#334155', marginBottom: '4px' }}>
                    City *
                  </label>
                  <input
                    type="text"
                    required
                    placeholder="e.g. Faisalabad, Lahore"
                    value={city}
                    onChange={(e) => setCity(e.target.value)}
                    style={{ width: '100%', padding: '10px 12px', borderRadius: '8px', border: '1px solid #cbd5e1' }}
                  />
                </div>
                <div>
                  <label style={{ display: 'block', fontSize: '0.85rem', fontWeight: 700, color: '#334155', marginBottom: '4px' }}>
                    Area / Landmark / Location
                  </label>
                  <input
                    type="text"
                    placeholder="e.g. D-Ground, Canal Road, Bypass"
                    value={areaLandmark}
                    onChange={(e) => setAreaLandmark(e.target.value)}
                    style={{ width: '100%', padding: '10px 12px', borderRadius: '8px', border: '1px solid #cbd5e1' }}
                  />
                </div>
              </div>

              {/* Fuel, Liters & Rate */}
              <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr 1fr', gap: '10px' }}>
                <div>
                  <label style={{ display: 'block', fontSize: '0.85rem', fontWeight: 700, color: '#334155', marginBottom: '4px' }}>
                    Fuel Type
                  </label>
                  <select
                    value={fuelType}
                    onChange={(e) => setFuelType(e.target.value)}
                    style={{ width: '100%', padding: '10px 12px', borderRadius: '8px', border: '1px solid #cbd5e1' }}
                  >
                    <option value="diesel">Diesel</option>
                    <option value="petrol">Petrol</option>
                    <option value="cng">CNG</option>
                  </select>
                </div>
                <div>
                  <label style={{ display: 'block', fontSize: '0.85rem', fontWeight: 700, color: '#334155', marginBottom: '4px' }}>
                    Liters *
                  </label>
                  <input
                    type="number"
                    step="0.01"
                    min="1"
                    required
                    placeholder="e.g. 50"
                    value={liters}
                    onChange={(e) => setLiters(e.target.value)}
                    style={{ width: '100%', padding: '10px 12px', borderRadius: '8px', border: '1px solid #cbd5e1' }}
                  />
                </div>
                <div>
                  <label style={{ display: 'block', fontSize: '0.85rem', fontWeight: 700, color: '#334155', marginBottom: '4px' }}>
                    Price / Liter (PKR) *
                  </label>
                  <input
                    type="number"
                    step="0.01"
                    min="1"
                    required
                    placeholder="285"
                    value={pricePerLiter}
                    onChange={(e) => setPricePerLiter(e.target.value)}
                    style={{ width: '100%', padding: '10px 12px', borderRadius: '8px', border: '1px solid #cbd5e1' }}
                  />
                </div>
              </div>

              {/* Calculation Summary Box */}
              <div style={{ padding: '12px', background: '#f8fafc', borderRadius: '8px', border: '1px solid #e2e8f0', display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
                <div>
                  <span style={{ fontSize: '0.8rem', color: '#64748b' }}>TOTAL CALCULATED CASH:</span>
                  <div style={{ fontSize: '1.25rem', fontWeight: 800, color: '#0f172a' }}>
                    {formatMoney(calculatedTotal)}
                  </div>
                </div>
                {calculatedAvg && (
                  <div style={{ textAlign: 'right' }}>
                    <span style={{ fontSize: '0.8rem', color: '#64748b' }}>ESTIMATED AVERAGE:</span>
                    <div style={{ fontSize: '1.1rem', fontWeight: 800, color: '#16a34a' }}>
                      {calculatedAvg} km / Liter
                    </div>
                  </div>
                )}
              </div>

              {/* Payment Mode & Distance */}
              <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '10px' }}>
                <div>
                  <label style={{ display: 'block', fontSize: '0.85rem', fontWeight: 700, color: '#334155', marginBottom: '4px' }}>
                    Payment Mode
                  </label>
                  <select
                    value={paymentMode}
                    onChange={(e) => setPaymentMode(e.target.value)}
                    style={{ width: '100%', padding: '10px 12px', borderRadius: '8px', border: '1px solid #cbd5e1' }}
                  >
                    <option value="cash">Cash (Driver Paid)</option>
                    <option value="driver_wallet">Driver App Wallet</option>
                    <option value="transporter_account">Transporter Fleet Account</option>
                    <option value="company_card">Fuel Station Fleet Card</option>
                  </select>
                </div>
                <div>
                  <label style={{ display: 'block', fontSize: '0.85rem', fontWeight: 700, color: '#334155', marginBottom: '4px' }}>
                    Trip Distance (km)
                  </label>
                  <input
                    type="number"
                    step="0.1"
                    placeholder="e.g. 150"
                    value={tripDistanceKm}
                    onChange={(e) => setTripDistanceKm(e.target.value)}
                    style={{ width: '100%', padding: '10px 12px', borderRadius: '8px', border: '1px solid #cbd5e1' }}
                  />
                </div>
              </div>

              {/* Refuel Date & Notes */}
              <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '10px' }}>
                <div>
                  <label style={{ display: 'block', fontSize: '0.85rem', fontWeight: 700, color: '#334155', marginBottom: '4px' }}>
                    Refuel Date
                  </label>
                  <input
                    type="date"
                    required
                    value={fuelDate}
                    onChange={(e) => setFuelDate(e.target.value)}
                    style={{ width: '100%', padding: '10px 12px', borderRadius: '8px', border: '1px solid #cbd5e1' }}
                  />
                </div>
                <div>
                  <label style={{ display: 'block', fontSize: '0.85rem', fontWeight: 700, color: '#334155', marginBottom: '4px' }}>
                    Odometer (km reading)
                  </label>
                  <input
                    type="number"
                    step="0.1"
                    placeholder="e.g. 84210"
                    value={odometerKm}
                    onChange={(e) => setOdometerKm(e.target.value)}
                    style={{ width: '100%', padding: '10px 12px', borderRadius: '8px', border: '1px solid #cbd5e1' }}
                  />
                </div>
              </div>

              <div>
                <label style={{ display: 'block', fontSize: '0.85rem', fontWeight: 700, color: '#334155', marginBottom: '4px' }}>
                  Notes / Receipt Remark
                </label>
                <input
                  type="text"
                  placeholder="e.g. Tank full before motorway entry"
                  value={notes}
                  onChange={(e) => setNotes(e.target.value)}
                  style={{ width: '100%', padding: '10px 12px', borderRadius: '8px', border: '1px solid #cbd5e1' }}
                />
              </div>

              <div style={{ display: 'flex', justifyContent: 'flex-end', gap: '10px', marginTop: '10px' }}>
                <button
                  type="button"
                  onClick={() => setShowAddModal(false)}
                  style={{ padding: '10px 18px', background: '#f1f5f9', border: 'none', borderRadius: '8px', fontWeight: 600, cursor: 'pointer' }}
                >
                  Cancel
                </button>
                <button
                  type="submit"
                  disabled={submitting}
                  style={{ padding: '10px 22px', background: '#2563eb', color: 'white', border: 'none', borderRadius: '8px', fontWeight: 700, cursor: 'pointer' }}
                >
                  {submitting ? 'Saving...' : 'Save Fuel Log'}
                </button>
              </div>
            </form>
          </div>
        </div>
      )}
    </div>
  )
}

import { useEffect, useState } from 'react'
import { apiGet, apiSend, formatMoney } from '../client/clientUtils'

export default function DriverTrips() {
  const [trips, setTrips] = useState([])
  const [contracts, setContracts] = useState([])
  const [loading, setLoading] = useState(true)
  const [actionId, setActionId] = useState(null)
  const [contractActionId, setContractActionId] = useState(null)
  const [msg, setMsg] = useState('')

  function loadData() {
    setLoading(true)
    Promise.all([
      apiGet('/api/driver/me'),
      apiGet('/api/driver/hire-contracts'),
    ])
      .then(([driverRes, contractsRes]) => {
        if (driverRes.success) setTrips(driverRes.recent_trips || [])
        if (contractsRes.success) setContracts(contractsRes.contracts || [])
      })
      .finally(() => setLoading(false))
  }

  useEffect(() => {
    loadData()
  }, [])

  async function handleResponse(id, action) {
    setActionId(id)
    try {
      const res = await apiSend(`/api/driver/trips/${id}/respond`, { action })
      if (res.success) {
        setMsg(`Trip ${action === 'accept' ? 'Accepted' : 'Rejected'} successfully!`)
        loadData()
      }
    } catch (err) {
      setMsg(`Error: ${err.message}`)
    } finally {
      setActionId(null)
    }
  }

  async function handleContractResponse(id, action) {
    setContractActionId(id)
    try {
      const res = await apiSend(`/api/driver/hire-contracts/${id}/respond`, { action })
      if (res.success) {
        setMsg(res.message || `Contract ${action === 'accept' ? 'Accepted' : 'Declined'} successfully!`)
        loadData()
      }
    } catch (err) {
      setMsg(`Error: ${err.message}`)
    } finally {
      setContractActionId(null)
    }
  }

  return (
    <div>
      {/* Permanent Hire Invitations Section */}
      <div className="driver-card" style={{ borderLeft: '4px solid #3b82f6' }}>
        <div style={{ display: 'flex', alignItems: 'center', gap: '10px' }}>
          <i className="fas fa-handshake" style={{ fontSize: '1.4rem', color: '#2563eb' }}></i>
          <h2 style={{ margin: 0, fontSize: '1.4rem', fontWeight: 800 }}>Permanent Monthly Hire Invitations</h2>
        </div>
        <p style={{ margin: '4px 0 0 0', color: '#64748b' }}>
          Fleet owners can offer you permanent monthly employment with a fixed salary once you build a strong rating.
        </p>

        {contracts.length === 0 ? (
          <p style={{ marginTop: '14px', color: '#64748b', fontSize: '0.9rem' }}>
            No permanent contract invitations right now. Complete freelance trips with high ratings to receive permanent offers!
          </p>
        ) : (
          <div style={{ marginTop: '16px', display: 'flex', flexDirection: 'column', gap: '14px' }}>
            {contracts.map((c) => (
              <div
                key={c.id}
                style={{
                  border: '1px solid #bfdbfe',
                  borderRadius: '10px',
                  padding: '18px',
                  background: '#f0f7ff',
                  display: 'flex',
                  justifyContent: 'space-between',
                  alignItems: 'center',
                  flexWrap: 'wrap',
                  gap: '16px',
                }}
              >
                <div>
                  <div style={{ display: 'flex', alignItems: 'center', gap: '8px' }}>
                    <strong style={{ fontSize: '1.1rem', color: '#1e3a8a' }}>{c.transporter_name}</strong>
                    <span style={{ fontSize: '0.8rem', background: '#dbeafe', color: '#1d4ed8', padding: '2px 8px', borderRadius: '4px', fontWeight: 700 }}>
                      Monthly Permanent Offer
                    </span>
                  </div>
                  <p style={{ margin: '4px 0 0 0', color: '#334155' }}>
                    Fixed Monthly Salary: <strong style={{ color: '#16a34a', fontSize: '1.1rem' }}>{formatMoney(c.monthly_salary)} / month</strong> &middot; Duration: {c.contract_months} Months
                  </p>
                  <p style={{ margin: '2px 0 0 0', fontSize: '0.85rem', color: '#64748b' }}>
                    Contact: {c.transporter_phone} &middot; {c.transporter_email}
                  </p>
                  {c.terms && (
                    <p style={{ margin: '6px 0 0 0', fontSize: '0.85rem', color: '#475569', fontStyle: 'italic' }}>
                      &quot;{c.terms}&quot;
                    </p>
                  )}
                </div>

                <div>
                  {c.status === 'offered' ? (
                    <div style={{ display: 'flex', gap: '8px' }}>
                      <button
                        type="button"
                        disabled={contractActionId === c.id}
                        onClick={() => handleContractResponse(c.id, 'accept')}
                        style={{
                          background: '#16a34a',
                          color: 'white',
                          border: 'none',
                          padding: '10px 18px',
                          borderRadius: '8px',
                          fontWeight: 700,
                          cursor: 'pointer',
                        }}
                      >
                        Accept Permanent Job
                      </button>
                      <button
                        type="button"
                        disabled={contractActionId === c.id}
                        onClick={() => handleContractResponse(c.id, 'decline')}
                        style={{
                          background: '#ef4444',
                          color: 'white',
                          border: 'none',
                          padding: '10px 18px',
                          borderRadius: '8px',
                          fontWeight: 700,
                          cursor: 'pointer',
                        }}
                      >
                        Decline
                      </button>
                    </div>
                  ) : (
                    <span
                      style={{
                        padding: '6px 14px',
                        borderRadius: '9999px',
                        fontWeight: 700,
                        fontSize: '0.85rem',
                        background: c.status === 'active' ? '#dcfce7' : '#f1f5f9',
                        color: c.status === 'active' ? '#166534' : '#64748b',
                      }}
                    >
                      {c.status === 'active' ? 'ACTIVE PERMANENT EMPLOYMENT' : c.status.toUpperCase()}
                    </span>
                  )}
                </div>
              </div>
            ))}
          </div>
        )}
      </div>

      {/* Per-Trip Requests Section */}
      <div className="driver-card">
        <h1 style={{ margin: 0, fontSize: '1.6rem', fontWeight: 800 }}>Per-Trip Dispatch Requests</h1>
        <p style={{ margin: '4px 0 0 0', color: '#64748b' }}>
          Accept or decline one-time freight trips assigned to you by fleet transporters.
        </p>

        {msg && (
          <div style={{ marginTop: '16px', padding: '12px', background: '#eff6ff', color: '#1e40af', borderRadius: '8px' }}>
            {msg}
          </div>
        )}

        {loading ? (
          <p style={{ marginTop: '20px' }}>Loading requests...</p>
        ) : trips.length === 0 ? (
          <p style={{ marginTop: '20px', color: '#64748b' }}>No trip requests found right now.</p>
        ) : (
          <div style={{ marginTop: '20px', display: 'flex', flexDirection: 'column', gap: '16px' }}>
            {trips.map((trip) => (
              <div
                key={trip.id}
                style={{
                  border: '1px solid #e2e8f0',
                  borderRadius: '10px',
                  padding: '20px',
                  background: 'white',
                  display: 'flex',
                  justifyContent: 'space-between',
                  alignItems: 'center',
                  flexWrap: 'wrap',
                  gap: '16px',
                }}
              >
                <div>
                  <div style={{ display: 'flex', alignItems: 'center', gap: '10px' }}>
                    <h3 style={{ margin: 0, fontSize: '1.15rem' }}>Truck: {trip.truck_number}</h3>
                    <span style={{ fontSize: '0.8rem', background: '#f1f5f9', padding: '3px 8px', borderRadius: '6px' }}>
                      {trip.truck_model}
                    </span>
                  </div>
                  <p style={{ margin: '6px 0 0 0', color: '#475569', fontSize: '0.9rem' }}>
                    Transporter: <strong>{trip.transporter_name}</strong> &middot; Phone: {trip.transporter_phone}
                  </p>
                  <p style={{ margin: '4px 0 0 0', color: '#16a34a', fontWeight: 700 }}>
                    Per-Trip Compensation: {formatMoney(trip.offer_amount || 0)}
                  </p>
                  {trip.notes && (
                    <p style={{ margin: '6px 0 0 0', fontSize: '0.85rem', color: '#64748b', fontStyle: 'italic' }}>
                      &quot;{trip.notes}&quot;
                    </p>
                  )}
                </div>

                <div>
                  {trip.status === 'requested' ? (
                    <div style={{ display: 'flex', gap: '8px' }}>
                      <button
                        type="button"
                        disabled={actionId === trip.id}
                        onClick={() => handleResponse(trip.id, 'accept')}
                        style={{
                          background: '#16a34a',
                          color: 'white',
                          border: 'none',
                          padding: '10px 18px',
                          borderRadius: '8px',
                          fontWeight: 700,
                          cursor: 'pointer',
                        }}
                      >
                        Accept Trip
                      </button>
                      <button
                        type="button"
                        disabled={actionId === trip.id}
                        onClick={() => handleResponse(trip.id, 'reject')}
                        style={{
                          background: '#ef4444',
                          color: 'white',
                          border: 'none',
                          padding: '10px 18px',
                          borderRadius: '8px',
                          fontWeight: 700,
                          cursor: 'pointer',
                        }}
                      >
                        Reject
                      </button>
                    </div>
                  ) : (
                    <span
                      style={{
                        padding: '6px 14px',
                        borderRadius: '9999px',
                        fontWeight: 700,
                        fontSize: '0.85rem',
                        background: trip.status === 'accepted' ? '#dcfce7' : '#f1f5f9',
                        color: trip.status === 'accepted' ? '#166534' : '#64748b',
                      }}
                    >
                      {trip.status.toUpperCase()}
                    </span>
                  )}
                </div>
              </div>
            ))}
          </div>
        )}
      </div>
    </div>
  )
}

import { useEffect, useState } from 'react'
import { useApi } from '../../hooks/useApi'
import FuelStationLayout from '../../components/fuelstation/FuelStationLayout'

const FUEL_OPTIONS = [
  { value: 'diesel', label: 'High Speed Diesel (HSD)' },
  { value: 'petrol', label: 'Super Petrol (Euro 5)' },
  { value: 'hi_octane', label: 'Hi-Octane 97' },
  { value: 'cng', label: 'Compressed Natural Gas (CNG)' },
  { value: 'adblue', label: 'AdBlue / DEF Fluid' },
]

export default function FuelPumpsPage() {
  const api = useApi()
  const [pumps, setPumps] = useState([])
  const [loading, setLoading] = useState(true)
  const [editingId, setEditingId] = useState(null)
  const [editForm, setEditForm] = useState({})
  const [showAddModal, setShowAddModal] = useState(false)
  const [newPump, setNewPump] = useState({
    pump_number: '',
    fuel_type: 'diesel',
    price_per_liter: '282.50',
    tank_capacity_liters: '25000',
    current_stock_liters: '18000',
  })
  const [notice, setNotice] = useState('')
  const [error, setError] = useState('')

  useEffect(() => {
    loadPumps()
  }, [])

  function loadPumps() {
    setLoading(true)
    api.get('/api/fuelstation/pumps')
      .then(res => {
        if (res.success) setPumps(res.pumps || [])
      })
      .catch(() => setError('Unable to load pumps from server.'))
      .finally(() => setLoading(false))
  }

  function startEdit(pump) {
    setEditingId(pump.id)
    setEditForm({
      pump_number: pump.pump_number,
      fuel_type: pump.fuel_type,
      price_per_liter: String(pump.price_per_liter),
      status: pump.status,
      current_stock_liters: String(pump.current_stock_liters),
      tank_capacity_liters: String(pump.tank_capacity_liters),
    })
  }

  async function handleSaveEdit(pumpId) {
    setError('')
    try {
      const res = await api.put(`/api/fuelstation/pumps/${pumpId}`, {
        pump_number: editForm.pump_number,
        fuel_type: editForm.fuel_type,
        price_per_liter: parseFloat(editForm.price_per_liter),
        status: editForm.status,
        current_stock_liters: parseFloat(editForm.current_stock_liters),
        tank_capacity_liters: parseFloat(editForm.tank_capacity_liters),
      })
      if (res.success) {
        setNotice('Pump rate & configuration updated successfully.')
        setEditingId(null)
        loadPumps()
      } else {
        setError(res.message || 'Failed to update pump.')
      }
    } catch (err) {
      setError(err.message || 'Failed to save changes.')
    }
  }

  async function handleAddPump(e) {
    e.preventDefault()
    setError('')
    try {
      const res = await api.post('/api/fuelstation/pumps', {
        pump_number: newPump.pump_number,
        fuel_type: newPump.fuel_type,
        price_per_liter: parseFloat(newPump.price_per_liter),
        tank_capacity_liters: parseFloat(newPump.tank_capacity_liters),
        current_stock_liters: parseFloat(newPump.current_stock_liters),
      })
      if (res.success) {
        setNotice('New pump added successfully!')
        setShowAddModal(false)
        setNewPump({ pump_number: '', fuel_type: 'diesel', price_per_liter: '282.50', tank_capacity_liters: '25000', current_stock_liters: '18000' })
        loadPumps()
      } else {
        setError(res.message || 'Failed to add pump.')
      }
    } catch (err) {
      setError(err.message || 'Error creating pump.')
    }
  }

  return (
    <FuelStationLayout>
      {notice && (
        <div style={{ background: '#ecf9f4', border: '1px solid #c4eadc', color: '#176b54', padding: '10px 14px', borderRadius: 8, marginBottom: 16 }}>
          <i className="fa-solid fa-circle-check" style={{ marginRight: 6 }} /> {notice}
        </div>
      )}

      {error && (
        <div style={{ background: '#fff0f0', border: '1px solid #ffcaca', color: '#a93737', padding: '10px 14px', borderRadius: 8, marginBottom: 16 }}>
          <i className="fa-solid fa-circle-exclamation" style={{ marginRight: 6 }} /> {error}
        </div>
      )}

      <div className="fuel-card">
        <div className="fuel-card__header">
          <div>
            <h2>Pumps, Dispensers &amp; Live Fuel Rates</h2>
            <p style={{ margin: '4px 0 0', fontSize: 13, color: '#94a3b8' }}>
              Set PKR rates per liter, view tank stock levels, and toggle pump maintenance status.
            </p>
          </div>
          <button
            className="fuel-btn fuel-btn--primary"
            onClick={() => setShowAddModal(true)}
          >
            <i className="fa-solid fa-plus" /> Add Dispenser Pump
          </button>
        </div>

        <div className="fuel-table-wrapper">
          <table className="fuel-table">
            <thead>
              <tr>
                <th>Bay / Nozzle</th>
                <th>Fuel Grade</th>
                <th>Price per Liter (PKR)</th>
                <th>Current Stock</th>
                <th>Tank Capacity</th>
                <th>Status</th>
                <th>Action</th>
              </tr>
            </thead>
            <tbody>
              {pumps.map(p => {
                const isEditing = editingId === p.id
                return (
                  <tr key={p.id}>
                    <td>
                      {isEditing ? (
                        <input
                          type="text"
                          className="fuel-form-input"
                          style={{ padding: '6px 10px', fontSize: 13 }}
                          value={editForm.pump_number}
                          onChange={e => setEditForm({ ...editForm, pump_number: e.target.value })}
                        />
                      ) : (
                        <strong>{p.pump_number}</strong>
                      )}
                    </td>

                    <td>
                      {isEditing ? (
                        <select
                          className="fuel-form-select"
                          style={{ padding: '6px 10px', fontSize: 13 }}
                          value={editForm.fuel_type}
                          onChange={e => setEditForm({ ...editForm, fuel_type: e.target.value })}
                        >
                          {FUEL_OPTIONS.map(opt => <option key={opt.value} value={opt.value}>{opt.label}</option>)}
                        </select>
                      ) : (
                        p.fuel_type_label
                      )}
                    </td>

                    <td>
                      {isEditing ? (
                        <input
                          type="number"
                          step="0.01"
                          className="fuel-form-input"
                          style={{ padding: '6px 10px', fontSize: 13, width: 120 }}
                          value={editForm.price_per_liter}
                          onChange={e => setEditForm({ ...editForm, price_per_liter: e.target.value })}
                        />
                      ) : (
                        <strong style={{ color: '#22c55e', fontSize: 15 }}>Rs. {p.price_per_liter.toFixed(2)}</strong>
                      )}
                    </td>

                    <td>
                      {isEditing ? (
                        <input
                          type="number"
                          step="100"
                          className="fuel-form-input"
                          style={{ padding: '6px 10px', fontSize: 13, width: 120 }}
                          value={editForm.current_stock_liters}
                          onChange={e => setEditForm({ ...editForm, current_stock_liters: e.target.value })}
                        />
                      ) : (
                        `${p.current_stock_liters.toLocaleString()} Liters`
                      )}
                    </td>

                    <td>{p.tank_capacity_liters.toLocaleString()} Liters</td>

                    <td>
                      {isEditing ? (
                        <select
                          className="fuel-form-select"
                          style={{ padding: '6px 10px', fontSize: 13 }}
                          value={editForm.status}
                          onChange={e => setEditForm({ ...editForm, status: e.target.value })}
                        >
                          <option value="active">Active</option>
                          <option value="maintenance">Maintenance</option>
                          <option value="inactive">Inactive</option>
                        </select>
                      ) : (
                        <span className={`fuel-badge fuel-badge--${p.status}`}>{p.status}</span>
                      )}
                    </td>

                    <td>
                      {isEditing ? (
                        <div style={{ display: 'flex', gap: 6 }}>
                          <button
                            className="fuel-btn fuel-btn--success"
                            style={{ padding: '6px 12px', fontSize: 12 }}
                            onClick={() => handleSaveEdit(p.id)}
                          >
                            Save
                          </button>
                          <button
                            className="fuel-btn"
                            style={{ padding: '6px 12px', fontSize: 12, background: '#475569', color: '#fff' }}
                            onClick={() => setEditingId(null)}
                          >
                            Cancel
                          </button>
                        </div>
                      ) : (
                        <button
                          className="fuel-btn"
                          style={{ padding: '6px 12px', fontSize: 12, background: '#334155', color: '#f59e0b' }}
                          onClick={() => startEdit(p)}
                        >
                          <i className="fa-solid fa-pen-to-square" /> Edit Rate
                        </button>
                      )}
                    </td>
                  </tr>
                )
              })}
              {pumps.length === 0 && !loading && (
                <tr>
                  <td colSpan="7" style={{ textAlign: 'center', padding: '32px', color: '#94a3b8' }}>
                    No pumps configured yet. Click "Add Dispenser Pump" above to set up your bays.
                  </td>
                </tr>
              )}
            </tbody>
          </table>
        </div>
      </div>

      {/* Add Pump Modal */}
      {showAddModal && (
        <div style={{ position: 'fixed', inset: 0, background: 'rgba(15,35,55,0.45)', backdropFilter: 'blur(4px)', display: 'flex', alignItems: 'center', justifyContent: 'center', zIndex: 100 }}>
          <div style={{ background: '#ffffff', border: '1px solid #dfe7f0', boxShadow: '0 24px 60px rgba(15,35,55,.2)', borderRadius: 14, padding: 28, width: 440, maxWidth: '90%' }}>
            <h3 style={{ margin: '0 0 16px', color: '#102a43' }}>Add New Dispenser Pump</h3>
            <form onSubmit={handleAddPump}>
              <div className="fuel-form-group">
                <label>Pump / Bay Name *</label>
                <input
                  type="text"
                  placeholder="e.g. Bay 5 - Heavy Diesel"
                  className="fuel-form-input"
                  value={newPump.pump_number}
                  onChange={e => setNewPump({ ...newPump, pump_number: e.target.value })}
                  required
                />
              </div>

              <div className="fuel-form-group">
                <label>Fuel Type *</label>
                <select
                  className="fuel-form-select"
                  value={newPump.fuel_type}
                  onChange={e => setNewPump({ ...newPump, fuel_type: e.target.value })}
                >
                  {FUEL_OPTIONS.map(opt => <option key={opt.value} value={opt.value}>{opt.label}</option>)}
                </select>
              </div>

              <div className="fuel-form-group">
                <label>Price per Liter (PKR) *</label>
                <input
                  type="number"
                  step="0.01"
                  className="fuel-form-input"
                  value={newPump.price_per_liter}
                  onChange={e => setNewPump({ ...newPump, price_per_liter: e.target.value })}
                  required
                />
              </div>

              <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: 12 }}>
                <div className="fuel-form-group">
                  <label>Tank Capacity (L)</label>
                  <input
                    type="number"
                    className="fuel-form-input"
                    value={newPump.tank_capacity_liters}
                    onChange={e => setNewPump({ ...newPump, tank_capacity_liters: e.target.value })}
                  />
                </div>
                <div className="fuel-form-group">
                  <label>Current Stock (L)</label>
                  <input
                    type="number"
                    className="fuel-form-input"
                    value={newPump.current_stock_liters}
                    onChange={e => setNewPump({ ...newPump, current_stock_liters: e.target.value })}
                  />
                </div>
              </div>

              <div style={{ display: 'flex', gap: 10, marginTop: 20 }}>
                <button type="submit" className="fuel-btn fuel-btn--primary" style={{ flex: 1 }}>
                  Create Pump
                </button>
                <button
                  type="button"
                  className="fuel-btn"
                  style={{ background: '#eef2f6', color: '#40566d', border: '1px solid #d9e2ec' }}
                  onClick={() => setShowAddModal(false)}
                >
                  Cancel
                </button>
              </div>
            </form>
          </div>
        </div>
      )}
    </FuelStationLayout>
  )
}

import { useEffect, useState } from 'react'
import { useApi } from '../../hooks/useApi'
import FuelStationLayout from '../../components/fuelstation/FuelStationLayout'

export default function FuelStationProfile() {
  const api = useApi()
  const [profile, setProfile] = useState({
    station_name: '',
    license_no: '',
    pumps_count: '',
    city: '',
    address: '',
    phone: '',
    email: '',
    full_name: '',
  })
  const [loading, setLoading] = useState(true)
  const [saving, setSaving] = useState(false)
  const [notice, setNotice] = useState('')
  const [error, setError] = useState('')

  useEffect(() => {
    api.get('/api/fuelstation/profile')
      .then(res => {
        if (res.success && res.profile) {
          setProfile(res.profile)
        }
      })
      .catch(() => setError('Failed to load profile.'))
      .finally(() => setLoading(false))
  }, [])

  async function handleSave(e) {
    e.preventDefault()
    setError('')
    setNotice('')
    setSaving(true)
    try {
      const res = await api.put('/api/fuelstation/profile', {
        station_name: profile.station_name,
        license_no: profile.license_no,
        pumps_count: profile.pumps_count,
        city: profile.city,
        address: profile.address,
        phone: profile.phone,
      })
      if (res.success) {
        setNotice('Station profile updated successfully!')
      } else {
        setError(res.message || 'Failed to update profile.')
      }
    } catch (err) {
      setError(err.message || 'Error saving profile.')
    } finally {
      setSaving(false)
    }
  }

  return (
    <FuelStationLayout>
      <div style={{ maxWidth: 700, margin: '0 auto' }}>
        <div className="fuel-card">
          <div className="fuel-card__header">
            <h2>Fuel Station &amp; Manager Profile</h2>
          </div>

          {notice && (
            <div style={{ background: '#ecf9f4', border: '1px solid #c4eadc', color: '#176b54', padding: '10px 14px', borderRadius: 8, marginBottom: 16 }}>
              <i className="fa-solid fa-circle-check" style={{ marginRight: 6 }} /> {notice}
            </div>
          )}

          {error && (
            <div style={{ background: '#fff0f0', border: '1px solid #ffcaca', color: '#a93737', padding: '10px 14px', borderRadius: 8, marginBottom: 16 }}>
              <i className="fa-solid fa-circle-exclamation" style={{ marginRight: 6 }} /> {error}
            </div>
          )}

          <form onSubmit={handleSave}>
            <div className="fuel-form-group">
              <label>Station Name *</label>
              <input
                type="text"
                className="fuel-form-input"
                value={profile.station_name}
                onChange={e => setProfile({ ...profile, station_name: e.target.value })}
                required
              />
            </div>

