import { useState } from 'react'
import { useNavigate } from 'react-router-dom'

const COLUMN_TYPES = [
  { value: 'text',     label: 'Text' },
  { value: 'number',   label: 'Number' },
  { value: 'date',     label: 'Date' },
  { value: 'dropdown', label: 'Dropdown' },
]

function newColumn() {
  return { id: Date.now() + Math.random(), name: '', type: 'text', options: '' }
}

async function getCsrf() {
  const cached = sessionStorage.getItem('csrf_token')
  if (cached) return cached
  const res = await fetch('/auth/csrf-token', { credentials: 'include' })
  const data = await res.json()
  const token = data?.csrf_token || ''
  if (token) sessionStorage.setItem('csrf_token', token)
  return token
}

export default function CreateTable() {
  const navigate = useNavigate()
  const [tableName, setTableName] = useState('')
  const [columns, setColumns] = useState([newColumn()])
  const [errors, setErrors] = useState({})
  const [loading, setLoading] = useState(false)
  const [apiError, setApiError] = useState('')

  function addColumn() {
    setColumns(prev => [...prev, newColumn()])
  }

  function removeColumn(id) {
    setColumns(prev => prev.filter(c => c.id !== id))
  }

  function updateColumn(id, field, value) {
    setColumns(prev => prev.map(c => c.id === id ? { ...c, [field]: value } : c))
  }

  function validate() {
    const e = {}
    if (!tableName.trim()) e.tableName = 'Table name is required'
    columns.forEach((col, i) => {
      if (!col.name.trim()) e[`col_${i}`] = 'Column name is required'
    })
    return e
  }

  async function handleSubmit(e) {
    e.preventDefault()
    const errs = validate()
    if (Object.keys(errs).length) { setErrors(errs); return }
    setErrors({})
    setApiError('')
    setLoading(true)
    try {
      const csrf = await getCsrf()
      const payload = {
        name: tableName.trim(),
        columns: columns.map(c => ({
          name: c.name.trim(),
          type: c.type,
          ...(c.type === 'dropdown' ? { options: c.options } : {}),
        })),
      }
      const res = await fetch('/api/shopkeeper/tables', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json', 'X-CSRF-Token': csrf },
        credentials: 'include',
        body: JSON.stringify(payload),
      })
      const data = await res.json()
      if (data.csrf_token) sessionStorage.setItem('csrf_token', data.csrf_token)
      if (res.ok && data.success) {
        navigate(`/shopkeeper/table/${data.data.table_id}`)
      } else {
        setApiError(data.message || 'Failed to create table.')
      }
    } catch (_) {
      setApiError('Network error. Please try again.')
    } finally {
      setLoading(false)
    }
  }

  return (
    <div className="min-h-screen bg-gray-50">
      {/* Header */}
      <header className="bg-white border-b border-gray-200 px-4 py-3 flex items-center gap-3">
        <button onClick={() => navigate('/shopkeeper/dashboard')}
          className="text-gray-400 hover:text-gray-700 transition-colors text-sm">
          ← Back
        </button>
        <span className="text-gray-300">|</span>
        <span className="text-sm font-bold text-blue-500">DigiTransX</span>
        <span className="text-gray-300">|</span>
        <span className="text-sm font-semibold text-orange-600">Create Product Table</span>
      </header>

      <main className="max-w-2xl mx-auto px-4 py-8">
        <div className="bg-white rounded-xl shadow-sm border border-gray-200 p-6">
          <div className="mb-6">
            <h1 className="text-xl font-bold text-gray-800">Create Product Table</h1>
            <p className="text-sm text-gray-500 mt-1">
              Define the table name and its columns. You can add rows after creating it.
            </p>
          </div>

          {apiError && (
            <div className="mb-4 px-4 py-3 bg-red-50 border border-red-200 rounded-lg text-red-700 text-sm">
              {apiError}
            </div>
          )}

          <form onSubmit={handleSubmit}>
            {/* Table name */}
            <div className="mb-6">
              <label className="block text-sm font-semibold text-gray-700 mb-1.5">
                Table Name <span className="text-red-500">*</span>
              </label>
              <input
                type="text"
                value={tableName}
                onChange={e => setTableName(e.target.value)}
                placeholder="e.g. Mobile Phones, Shoes, Groceries"
                className={`w-full px-4 py-3 border-2 rounded-lg text-sm outline-none transition-all
                  focus:border-orange-400 focus:ring-2 focus:ring-orange-100
                  ${errors.tableName ? 'border-red-400' : 'border-gray-200'}`}
              />
              {errors.tableName && <p className="text-red-500 text-xs mt-1">{errors.tableName}</p>}
            </div>

            {/* Columns */}
            <div className="mb-6">
              <div className="flex items-center justify-between mb-3">
                <label className="text-sm font-semibold text-gray-700">
                  Columns <span className="text-red-500">*</span>
                </label>
                <button type="button" onClick={addColumn}
                  className="text-xs px-3 py-1.5 bg-orange-50 hover:bg-orange-100 text-orange-600 font-medium rounded-lg border border-orange-200 transition-colors">
                  + Add Column
                </button>
              </div>

              <div className="space-y-3">
                {columns.map((col, i) => (
                  <div key={col.id} className="flex gap-2 items-start p-3 bg-gray-50 rounded-lg border border-gray-200">
                    <div className="flex-1 min-w-0">
                      <input
                        type="text"
                        value={col.name}
                        onChange={e => updateColumn(col.id, 'name', e.target.value)}
                        placeholder={`Column ${i + 1} name (e.g. Price)`}
                        className={`w-full px-3 py-2 border-2 rounded-lg text-sm outline-none transition-all
                          focus:border-orange-400 focus:ring-2 focus:ring-orange-100 bg-white
                          ${errors[`col_${i}`] ? 'border-red-400' : 'border-gray-200'}`}
                      />
                      {errors[`col_${i}`] && <p className="text-red-500 text-xs mt-1">{errors[`col_${i}`]}</p>}
                    </div>

                    <select
                      value={col.type}
                      onChange={e => updateColumn(col.id, 'type', e.target.value)}
                      className="px-3 py-2 border-2 border-gray-200 rounded-lg text-sm outline-none focus:border-orange-400 bg-white text-gray-700 shrink-0">
                      {COLUMN_TYPES.map(t => (
                        <option key={t.value} value={t.value}>{t.label}</option>
                      ))}
                    </select>

                    {columns.length > 1 && (
                      <button type="button" onClick={() => removeColumn(col.id)}
                        className="px-2 py-2 text-gray-400 hover:text-red-500 transition-colors shrink-0 text-lg leading-none">
                        ×
                      </button>
                    )}

                    {col.type === 'dropdown' && (
                      <div className="w-full mt-2 col-span-full">
                        <input
                          type="text"
                          value={col.options}
                          onChange={e => updateColumn(col.id, 'options', e.target.value)}
                          placeholder="Options separated by commas: Red, Blue, Green"
                          className="w-full px-3 py-2 border-2 border-gray-200 rounded-lg text-sm outline-none focus:border-orange-400 focus:ring-2 focus:ring-orange-100 bg-white"
                        />
                        <p className="text-xs text-gray-400 mt-1">Enter options separated by commas</p>
                      </div>
                    )}
                  </div>
                ))}
              </div>
            </div>

            {/* Column type legend */}
            <div className="mb-6 p-3 bg-blue-50 rounded-lg border border-blue-100">
              <p className="text-xs text-blue-700 font-medium mb-1">Column types:</p>
              <div className="flex flex-wrap gap-3 text-xs text-blue-600">
                <span><strong>Text</strong> — names, descriptions</span>
                <span><strong>Number</strong> — prices, quantities</span>
                <span><strong>Date</strong> — dates, deadlines</span>
                <span><strong>Dropdown</strong> — fixed choices</span>
              </div>
            </div>

            <div className="flex gap-3">
              <button type="button" onClick={() => navigate('/shopkeeper/dashboard')}
                className="flex-1 py-3 border-2 border-gray-200 text-gray-600 font-semibold rounded-lg hover:bg-gray-50 transition-colors text-sm">
                Cancel
              </button>
              <button type="submit" disabled={loading}
                className="flex-1 py-3 bg-orange-500 hover:bg-orange-600 disabled:bg-gray-400 text-white font-semibold rounded-lg transition-colors text-sm flex items-center justify-center gap-2">
                {loading && <span className="w-4 h-4 border-2 border-white/30 border-t-white rounded-full animate-spin" />}
                {loading ? 'Creating...' : 'Create Table'}
              </button>
            </div>
          </form>
        </div>
      </main>
    </div>
  )
}

import { useEffect, useRef, useState } from 'react'
import { useNavigate, useParams } from 'react-router-dom'

async function getCsrf() {
  const cached = sessionStorage.getItem('csrf_token')
  if (cached) return cached
  const res = await fetch('/auth/csrf-token', { credentials: 'include' })
  const data = await res.json()
  const token = data?.csrf_token || ''
  if (token) sessionStorage.setItem('csrf_token', token)
  return token
}

function emptyRow(columns) {
  return Object.fromEntries(columns.map(c => [c.name, '']))
}

export default function TableView() {
  const { tableId } = useParams()
  const navigate = useNavigate()

  const [tableData, setTableData] = useState(null)
  const [loading, setLoading] = useState(true)
  const [error, setError] = useState('')

  // editing state: { rowId: number|'new', field: string }
  const [editing, setEditing] = useState(null)
  const [editValue, setEditValue] = useState('')
  const [savingRow, setSavingRow] = useState(null)
  const [deletingRow, setDeletingRow] = useState(null)

  // new row buffer
  const [newRowValues, setNewRowValues] = useState(null)
  const [addingRow, setAddingRow] = useState(false)

  const inputRef = useRef(null)

  function fetchTable() {
    return fetch(`/api/shopkeeper/tables/${tableId}`, { credentials: 'include' })
      .then(r => r.json())
      .then(data => {
        if (data.success) {
          setTableData(data.data)
          if (data.csrf_token) sessionStorage.setItem('csrf_token', data.csrf_token)
        } else {
          setError(data.message || 'Failed to load table.')
        }
      })
      .catch(() => setError('Network error. Please refresh.'))
  }

  useEffect(() => {
    fetchTable().finally(() => setLoading(false))
  }, [tableId])

  useEffect(() => {
    if (editing && inputRef.current) inputRef.current.focus()
  }, [editing])

  function startEdit(rowId, field, currentValue) {
    setEditing({ rowId, field })
    setEditValue(String(currentValue ?? ''))
  }

  async function commitEdit(row) {
    if (!editing) return
    const { rowId, field } = editing
    setEditing(null)

    const newVal = editValue
    const origVal = String(row.values[field] ?? '')
    if (newVal === origVal) return

    setSavingRow(rowId)
    try {
      const csrf = await getCsrf()
      const res = await fetch(`/api/shopkeeper/tables/${tableId}/rows/${rowId}`, {
        method: 'PUT',
        headers: { 'Content-Type': 'application/json', 'X-CSRF-Token': csrf },
        credentials: 'include',
        body: JSON.stringify({ values: { [field]: newVal } }),
      })
      const data = await res.json()
      if (data.csrf_token) sessionStorage.setItem('csrf_token', data.csrf_token)
      if (data.success) {
        setTableData(prev => ({
          ...prev,
          rows: prev.rows.map(r => r.id === rowId
            ? { ...r, values: { ...r.values, [field]: newVal } }
            : r
          ),
        }))
      }
    } catch (_) {}
    finally { setSavingRow(null) }
  }

  async function deleteRow(rowId) {
    if (!window.confirm('Delete this row?')) return
    setDeletingRow(rowId)
    try {
      const csrf = await getCsrf()
      const res = await fetch(`/api/shopkeeper/tables/${tableId}/rows/${rowId}`, {
        method: 'DELETE',
        headers: { 'Content-Type': 'application/json', 'X-CSRF-Token': csrf },
        credentials: 'include',
      })
      const data = await res.json()
      if (data.csrf_token) sessionStorage.setItem('csrf_token', data.csrf_token)
      if (data.success) {
        setTableData(prev => ({ ...prev, rows: prev.rows.filter(r => r.id !== rowId) }))
      }
    } catch (_) {}
    finally { setDeletingRow(null) }
  }

  function startAddRow() {
    if (!tableData) return
    setNewRowValues(emptyRow(tableData.columns))
    setAddingRow(false)
  }

  async function submitNewRow() {
    if (!newRowValues || addingRow) return
    setAddingRow(true)
    try {
      const csrf = await getCsrf()
      const res = await fetch(`/api/shopkeeper/tables/${tableId}/rows`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json', 'X-CSRF-Token': csrf },
        credentials: 'include',
        body: JSON.stringify({ values: newRowValues }),
      })
      const data = await res.json()
      if (data.csrf_token) sessionStorage.setItem('csrf_token', data.csrf_token)
      if (data.success) {
        const newRow = { id: data.data.row_id, values: { ...newRowValues }, created_at: new Date().toISOString() }
        setTableData(prev => ({ ...prev, rows: [...prev.rows, newRow] }))
        setNewRowValues(null)
      }
    } catch (_) {}
    finally { setAddingRow(false) }
  }

  function renderCell(row, col) {
    const isEditing = editing?.rowId === row.id && editing?.field === col.name
    const isSaving  = savingRow === row.id

    if (isEditing) {
      if (col.type === 'dropdown' && col.options?.length > 0) {
        return (
          <select
            ref={inputRef}
            value={editValue}
            onChange={e => setEditValue(e.target.value)}
            onBlur={() => commitEdit(row)}
            className="w-full px-2 py-1 border border-orange-400 rounded text-sm outline-none bg-white">
            <option value="">—</option>
            {col.options.map(opt => <option key={opt} value={opt}>{opt}</option>)}
          </select>
        )
      }
      return (
        <input
          ref={inputRef}
          type={col.type === 'number' ? 'number' : col.type === 'date' ? 'date' : 'text'}
          value={editValue}
          onChange={e => setEditValue(e.target.value)}
          onBlur={() => commitEdit(row)}
          onKeyDown={e => { if (e.key === 'Enter') commitEdit(row); if (e.key === 'Escape') setEditing(null) }}
          className="w-full px-2 py-1 border border-orange-400 rounded text-sm outline-none bg-white"
        />
      )
    }

    const val = row.values[col.name] ?? ''
    return (
      <div
        onClick={() => !isSaving && startEdit(row.id, col.name, val)}
        className={`min-h-[28px] px-1 rounded cursor-pointer hover:bg-orange-50 transition-colors text-sm text-gray-700
          ${isSaving ? 'opacity-50 cursor-wait' : ''}`}
        title="Click to edit">
        {val !== '' && val !== null && val !== undefined ? String(val) : <span className="text-gray-300">—</span>}
      </div>
    )
  }

  if (loading) return (
    <div className="min-h-screen bg-gray-50 flex items-center justify-center">
      <div className="w-8 h-8 border-4 border-orange-500 border-t-transparent rounded-full animate-spin" />
    </div>
  )

  if (error) return (
    <div className="min-h-screen bg-gray-50 flex items-center justify-center">
      <div className="text-center">
        <p className="text-red-600 font-semibold">{error}</p>
        <button onClick={() => navigate('/shopkeeper/dashboard')}
          className="mt-4 text-sm text-blue-500 hover:underline">← Back to Dashboard</button>
      </div>
    </div>
  )

  const { columns = [], rows = [], name = '' } = tableData || {}

  return (
    <div className="min-h-screen bg-gray-50">
      {/* Header */}
      <header className="bg-white border-b border-gray-200 px-4 py-3 flex items-center justify-between">
        <div className="flex items-center gap-3">
          <button onClick={() => navigate('/shopkeeper/dashboard')}
            className="text-gray-400 hover:text-gray-700 transition-colors text-sm">
            ← Dashboard
          </button>
          <span className="text-gray-300">|</span>
          <span className="text-sm font-bold text-blue-500">DigiTransX</span>
          <span className="text-gray-300">|</span>
          <span className="text-sm font-semibold text-orange-600 truncate max-w-[160px]">{name}</span>
        </div>
        <button
          onClick={() => navigate(`/shopkeeper/table/${tableId}/analysis`)}
          className="flex items-center gap-1.5 px-3 py-1.5 bg-blue-500 hover:bg-blue-600 text-white text-xs font-semibold rounded-lg transition-colors">
          📈 Analysis
        </button>
      </header>

      <main className="max-w-full px-4 py-6">
        {/* Stats bar */}
        <div className="flex items-center gap-4 mb-4">
          <h1 className="text-xl font-bold text-gray-800">{name}</h1>
          <span className="text-sm text-gray-500 bg-gray-100 px-2 py-0.5 rounded-full">
            {rows.length} row{rows.length !== 1 ? 's' : ''}
          </span>
          <span className="text-sm text-gray-500 bg-gray-100 px-2 py-0.5 rounded-full">
            {columns.length} column{columns.length !== 1 ? 's' : ''}
          </span>
        </div>

        <p className="text-xs text-gray-400 mb-4">
          Click any cell to edit it. Press Enter or click away to save.
        </p>

        {/* Table */}
        <div className="bg-white rounded-xl border border-gray-200 shadow-sm overflow-auto">
          <table className="w-full border-collapse text-sm">
            <thead>
              <tr className="bg-gray-50 border-b border-gray-200">
                <th className="px-3 py-2.5 text-left text-xs font-semibold text-gray-500 w-10">#</th>
                {columns.map(col => (
                  <th key={col.name} className="px-3 py-2.5 text-left text-xs font-semibold text-gray-700 whitespace-nowrap">
                    {col.name}
                    <span className="ml-1 text-gray-400 font-normal">({col.type})</span>
                  </th>
                ))}
                <th className="px-3 py-2.5 w-10" />
              </tr>
            </thead>
            <tbody>
              {rows.map((row, idx) => (
                <tr key={row.id}
                  className={`border-b border-gray-100 hover:bg-orange-50/30 transition-colors
                    ${deletingRow === row.id ? 'opacity-40' : ''}`}>
                  <td className="px-3 py-2 text-xs text-gray-400">{idx + 1}</td>
                  {columns.map(col => (
                    <td key={col.name} className="px-3 py-2 min-w-[120px] max-w-[240px]">
                      {renderCell(row, col)}
                    </td>
                  ))}
                  <td className="px-3 py-2">
                    <button
                      onClick={() => deleteRow(row.id)}
                      disabled={!!deletingRow}
                      className="text-gray-300 hover:text-red-500 transition-colors text-lg leading-none disabled:cursor-wait"
                      title="Delete row">
                      ×
                    </button>
                  </td>
                </tr>
              ))}

              {/* New row inputs */}
              {newRowValues && (
                <tr className="border-b border-orange-200 bg-orange-50/40">
                  <td className="px-3 py-2 text-xs text-orange-400">new</td>
                  {columns.map(col => (
                    <td key={col.name} className="px-3 py-2 min-w-[120px]">
                      {col.type === 'dropdown' && col.options?.length > 0 ? (
                        <select
                          value={newRowValues[col.name] || ''}
                          onChange={e => setNewRowValues(p => ({ ...p, [col.name]: e.target.value }))}
                          className="w-full px-2 py-1.5 border border-orange-300 rounded text-sm outline-none bg-white focus:border-orange-500">
                          <option value="">—</option>
                          {col.options.map(opt => <option key={opt} value={opt}>{opt}</option>)}
                        </select>
                      ) : (
                        <input
                          type={col.type === 'number' ? 'number' : col.type === 'date' ? 'date' : 'text'}
                          value={newRowValues[col.name] || ''}
                          onChange={e => setNewRowValues(p => ({ ...p, [col.name]: e.target.value }))}
                          placeholder={col.name}
                          className="w-full px-2 py-1.5 border border-orange-300 rounded text-sm outline-none bg-white focus:border-orange-500 focus:ring-1 focus:ring-orange-200"
                        />
                      )}
                    </td>
                  ))}
                  <td className="px-3 py-2">
                    <button onClick={() => setNewRowValues(null)}
                      className="text-gray-400 hover:text-red-500 transition-colors text-lg leading-none">
                      ×
                    </button>
                  </td>
                </tr>
              )}

              {/* Empty state */}
              {rows.length === 0 && !newRowValues && (
                <tr>
                  <td colSpan={columns.length + 2}
                    className="px-4 py-10 text-center text-gray-400 text-sm">
                    No rows yet. Click "Add Row" to get started.
                  </td>
                </tr>
              )}
            </tbody>
          </table>
        </div>

        {/* Action bar */}
        <div className="flex items-center gap-3 mt-4">
          {!newRowValues ? (
            <button onClick={startAddRow}
              className="flex items-center gap-2 px-4 py-2 bg-orange-500 hover:bg-orange-600 text-white text-sm font-semibold rounded-lg transition-colors">
              + Add Row
            </button>
          ) : (
            <button onClick={submitNewRow} disabled={addingRow}
              className="flex items-center gap-2 px-4 py-2 bg-green-600 hover:bg-green-700 disabled:bg-gray-400 text-white text-sm font-semibold rounded-lg transition-colors">
              {addingRow && <span className="w-3 h-3 border-2 border-white/30 border-t-white rounded-full animate-spin" />}
              {addingRow ? 'Saving...' : 'Save Row'}
            </button>
          )}
          {newRowValues && (
            <button onClick={() => setNewRowValues(null)}
              className="px-4 py-2 border border-gray-200 text-gray-600 text-sm rounded-lg hover:bg-gray-50 transition-colors">
              Cancel
            </button>
          )}
          <button
            onClick={() => window.open(`/api/shopkeeper/tables/${tableId}/export`, '_blank')}
            className="ml-auto flex items-center gap-1.5 px-4 py-2 border border-gray-200 text-gray-600 text-sm rounded-lg hover:bg-gray-50 transition-colors">
            ↓ Export CSV
          </button>
          <button
            onClick={() => navigate(`/shopkeeper/table/${tableId}/analysis`)}
            className="flex items-center gap-1.5 px-4 py-2 bg-blue-500 hover:bg-blue-600 text-white text-sm font-semibold rounded-lg transition-colors">
            📈 Analysis
          </button>
        </div>
      </main>
    </div>
  )
}

import { useEffect, useMemo, useState } from 'react'
import { loadTruckCatalog } from '../../lib/truckCatalog'
import { PrimaryButton, SecondaryButton, StateMessage, apiGet, apiSend, formatMoney } from '../client/clientUtils'
import '../../styles/pages/agreement-bids.css'

function statusPill(status) {
  const value = String(status || 'open').replace(/_/g, ' ')
  return <span className={`agreementbids-status agreementbids-status--${String(status || 'open').toLowerCase()}`}>{value}</span>
}

function formatPostTime(value) {
  if (!value) return 'Time not set'
  const normalized = String(value).includes('T') ? value : String(value).replace(' ', 'T')
  const date = new Date(normalized)
  if (Number.isNaN(date.getTime())) return String(value)
  return date.toLocaleString('en-PK', {
    day: '2-digit',
    month: 'short',
    year: 'numeric',
    hour: '2-digit',
    minute: '2-digit',
  })
}

function routeParts(post) {
  const pickup = post.pickup_location || post.pickupLocation || post.pickup || post.pickup_city || post.pickupCity || ''
  const dropoff = post.dropoff_location || post.dropoffLocation || post.dropoff || post.drop_location || post.drop_city || post.dropCity || ''
  return {
    pickup,
    dropoff,
    hasRoute: Boolean(pickup && dropoff),
  }
}

export default function AgreementBids() {
  const [posts, setPosts] = useState([])
  const [trucks, setTrucks] = useState([])
  const [catalog, setCatalog] = useState([])
  const [selectedPostId, setSelectedPostId] = useState(null)
  const [message, setMessage] = useState('')
  const [rows, setRows] = useState([])
  const [loading, setLoading] = useState(true)
  const [submitting, setSubmitting] = useState(false)
  const [error, setError] = useState('')
  const [notice, setNotice] = useState('')

  async function loadData() {
    setLoading(true)
    setError('')
    try {
      const [postJson, truckJson, catalogJson] = await Promise.all([
        apiGet('/api/agreements/posts/available'),
        apiGet('/api/trucks'),
        loadTruckCatalog(),
      ])
      setPosts(postJson.posts || [])
      setTrucks(truckJson.trucks || [])
      setCatalog(catalogJson)
    } catch (loadError) {
      setError(loadError.message || 'Unable to load agreement bids.')
    } finally {
      setLoading(false)
    }
  }

  useEffect(() => {
    loadData()
  }, [])

  const selectedPost = useMemo(() => posts.find((post) => post.id === selectedPostId) || null, [posts, selectedPostId])
  const requiredTypes = useMemo(() => new Set((selectedPost?.trucks || []).map((truck) => truck.truck_type)), [selectedPost])
  const eligibleTrucks = useMemo(() => trucks.filter((truck) => truck.status === 'active' && truck.tracking_id && requiredTypes.has(truck.catalog_type_key)), [trucks, requiredTypes])

  function typeName(typeKey) {
    return catalog.find((item) => item.type_key === typeKey)?.display_name || typeKey
  }

  function postTruckTypes(post) {
    const names = (post.trucks || []).map((truck) => truck.truck_type_name || typeName(truck.truck_type)).filter(Boolean)
    return [...new Set(names)].join(', ') || 'Truck type not specified'
  }

  function postMeta(post) {
    return [post.cargo_type, post.service_area_text].filter(Boolean).join(' | ')
  }

  function openBid(post) {
    setSelectedPostId(post.id)
    setMessage('')
    setRows([{ truck_id: '', per_km_rate: '', minimum_monthly_guarantee: '' }])
    setError('')
    setNotice('')
  }

  function updateRow(index, field, value) {
    setRows((current) => current.map((row, rowIndex) => rowIndex === index ? { ...row, [field]: value } : row))
  }

  async function submitBid(event) {
    event.preventDefault()
    setSubmitting(true)
    setError('')
    setNotice('')
    try {
      await apiSend(`/api/agreements/posts/${selectedPost.id}/bids`, {
        message,
        trucks: rows.map((row) => ({
          truck_id: Number(row.truck_id),
          per_km_rate: Number(row.per_km_rate),
          minimum_monthly_guarantee: Number(row.minimum_monthly_guarantee),
        })),
      })
      setNotice('Agreement bid placed.')
      setSelectedPostId(null)
      await loadData()
    } catch (submitError) {
      setError(submitError.message || 'Unable to submit bid.')
    } finally {
      setSubmitting(false)
    }
  }

  return (
    <div className="agreementbids-page">
      <div className="agreementbids-page-title">
        <div>
          <h1>Agreement Bids</h1>
          <p>Open long-term posts matching your active GPS-enabled trucks.</p>
        </div>
      </div>
      {loading && <StateMessage type="loading">Loading agreement bids...</StateMessage>}
      {error && <StateMessage type="error">{error}</StateMessage>}
      {notice && <StateMessage type="success">{notice}</StateMessage>}
      {!loading && !error && posts.length === 0 && (
        <div className="agreementbids-empty-state">
          <i className="fas fa-file-signature" aria-hidden="true"></i>
          <p>No matching agreement bids right now.</p>
        </div>
      )}

      <div className="agreementbids-grid">
        {posts.map((post) => (
          <article key={post.id} className="agreementbids-card">
            {(() => {
              const route = routeParts(post)
              return (
                <>
            <div className="agreementbids-card-header">
              <div>
                <h2>{post.title}</h2>
                <p>{postMeta(post)}</p>
              </div>
              {statusPill(post.status)}
            </div>
            <div className="agreementbids-truck-type">
              <i className="fas fa-truck" aria-hidden="true"></i>
              <span>{postTruckTypes(post)}</span>
            </div>
            {route.hasRoute && (
              <div className="agreementbids-route">
                <span className="agreementbids-route-point">{route.pickup}</span>
                <i className="fas fa-arrow-right-long" aria-hidden="true"></i>
                <span className="agreementbids-route-point">{route.dropoff}</span>
              </div>
            )}
            <div className="agreementbids-time">
              <i className="fas fa-clock" aria-hidden="true"></i>
              <span>{formatPostTime(post.created_at || post.updated_at)}</span>
            </div>
            <PrimaryButton type="button" className="agreementbids-place-btn" onClick={() => openBid(post)}>
              <i className="fas fa-gavel" aria-hidden="true"></i>
              Place Bid
            </PrimaryButton>
                </>
              )
            })()}
          </article>
        ))}
      </div>

      {selectedPost && (
        <div className="agreementbids-form-panel">
          <div className="agreementbids-form-header">
            <div>
              <h2>Bid for {selectedPost.title}</h2>
              <p>Select GPS-enabled trucks and set monthly rates.</p>
            </div>
            <SecondaryButton type="button" onClick={() => setSelectedPostId(null)}>Close</SecondaryButton>
          </div>
          <form className="agreementbids-form" onSubmit={submitBid}>
            {rows.map((row, index) => (
              <div key={index} className="agreementbids-row">
                <label className="agreementbids-field">
                  <span>Truck</span>
                  <select value={row.truck_id} onChange={(event) => updateRow(index, 'truck_id', event.target.value)} required>
                    <option value="">Select truck</option>
                    {eligibleTrucks.map((truck) => <option key={truck.id} value={truck.id}>{truck.truck_number} - {truck.truck_type}</option>)}
                  </select>
                </label>
                <label className="agreementbids-field">
                  <span>Per KM rate</span>
                  <input type="number" min="0.01" step="0.01" value={row.per_km_rate} onChange={(event) => updateRow(index, 'per_km_rate', event.target.value)} required />
                </label>
                <label className="agreementbids-field">
                  <span>Monthly minimum</span>
                  <input type="number" min="0.01" step="0.01" value={row.minimum_monthly_guarantee} onChange={(event) => updateRow(index, 'minimum_monthly_guarantee', event.target.value)} required />
                </label>
              </div>
            ))}
            <label className="agreementbids-field agreementbids-field--message">
              <span>Message</span>
              <textarea value={message} onChange={(event) => setMessage(event.target.value)} />
            </label>
            <div className="agreementbids-form-actions">
              <SecondaryButton type="button" onClick={() => setRows((current) => [...current, { truck_id: '', per_km_rate: '', minimum_monthly_guarantee: '' }])}>
                <i className="fas fa-plus" aria-hidden="true"></i>
                Add truck
              </SecondaryButton>
              <PrimaryButton type="submit" disabled={submitting || eligibleTrucks.length === 0}>
                <i className={`fas ${submitting ? 'fa-spinner fa-spin' : 'fa-paper-plane'}`} aria-hidden="true"></i>
                Submit bid
              </PrimaryButton>
              {eligibleTrucks.length === 0 && <span className="agreementbids-warning">No eligible GPS-enabled truck for this post.</span>}
            </div>
          </form>
        </div>
      )}
    </div>
  )
}

import { useEffect, useMemo, useState } from 'react'
import { getCsrfToken } from '../client/clientUtils'

function formatMoney(value) {
  const amount = Number(value || 0)
  if (!Number.isFinite(amount)) return 'PKR 0'
  return `PKR ${amount.toLocaleString('en-PK', { maximumFractionDigits: 2 })}`
}

export default function AvailableBids() {
  const [orders, setOrders] = useState([])
  const [trucks, setTrucks] = useState([])
  const [locationSetupRequired, setLocationSetupRequired] = useState(false)
  const [ordersOutOfRange, setOrdersOutOfRange] = useState(0)
  const [selectedOrderId, setSelectedOrderId] = useState(null)
  const [form, setForm] = useState({ truck_id: '', bid_price: '', message: '' })
  const [loading, setLoading] = useState(true)
  const [submitting, setSubmitting] = useState(false)
  const [error, setError] = useState('')
  const [success, setSuccess] = useState('')

  async function loadData() {
    setLoading(true)
    setError('')
    try {
      const [ordersRes, trucksRes] = await Promise.all([
        fetch('/api/orders/available', { credentials: 'same-origin' }),
        fetch('/api/trucks', { credentials: 'same-origin' }),
      ])
      const ordersJson = await ordersRes.json().catch(() => ({}))
      const trucksJson = await trucksRes.json().catch(() => ({}))
      if (!ordersRes.ok || ordersJson.success === false) throw new Error(ordersJson.message || 'Unable to load available orders.')
      if (!trucksRes.ok || trucksJson.success === false) throw new Error(trucksJson.message || 'Unable to load trucks.')
      setOrders(ordersJson.orders || [])
      setTrucks(trucksJson.trucks || [])
      setLocationSetupRequired(Boolean(ordersJson.location_setup_required))
      setOrdersOutOfRange(Number(ordersJson.orders_out_of_range || 0))
    } catch (loadError) {
      setError(loadError.message || 'Unable to load available orders.')
    } finally {
      setLoading(false)
    }
  }

  useEffect(() => {
    loadData()
  }, [])

  const selectedOrder = useMemo(
    () => orders.find((order) => order.id === selectedOrderId) || null,
    [orders, selectedOrderId],
  )

  const activeTrucks = useMemo(() => {
    if (!selectedOrder) return []
    const requiredTypes = Array.isArray(selectedOrder.required_truck_types)
      ? selectedOrder.required_truck_types
      : []
    const orderWeight = Number(selectedOrder.goods_weight_tons || 0)

    return trucks.filter((truck) => {
      if (truck.status !== 'active') return false
      // Type match (if specified)
      if (requiredTypes.length > 0) {
        const truckKey = truck.catalog_type_key || truck.truck_type
        if (!requiredTypes.includes(truckKey)) return false
      }
      // Weight match (if order has positive weight)
      const truckCap = Number(truck.capacity_tons || truck.payload_max_tons || 0)
      if (orderWeight > 0 && truckCap > 0 && orderWeight > truckCap) {
        return false
      }
      return true
    })
  }, [selectedOrder, trucks])

  function openBidForm(order) {
    setSelectedOrderId(order.id)
    setSuccess('')
    setError('')
    setForm({ truck_id: '', bid_price: '', message: '' })
  }

  function updateForm(event) {
    const { name, value } = event.target
    setForm((current) => ({ ...current, [name]: value }))
  }

  async function submitBid(event) {
    event.preventDefault()
    if (!selectedOrder) return

    setSubmitting(true)
    setError('')
    setSuccess('')
    try {
      const csrf = await getCsrfToken()
      const response = await fetch(`/api/orders/${selectedOrder.id}/bids`, {
        method: 'POST',
        credentials: 'same-origin',
        headers: {
          'Content-Type': 'application/json',
          'X-CSRF-Token': csrf,
        },
        body: JSON.stringify({
          truck_id: Number(form.truck_id),
          bid_price: Number(form.bid_price),
          message: form.message,
        }),
      })
      const json = await response.json().catch(() => ({}))
      if (!response.ok || json.success === false) throw new Error(json.message || 'Unable to place bid.')
      setSuccess('Bid placed successfully.')
      setSelectedOrderId(null)
      setForm({ truck_id: '', bid_price: '', message: '' })
      await loadData()
    } catch (submitError) {
      setError(submitError.message || 'Unable to place bid.')
    } finally {
      setSubmitting(false)
    }
  }

  return (
      <div className="space-y-6">
        <div className="rounded-2xl bg-white p-6 shadow-sm">
          <h1 className="text-2xl font-bold text-slate-900">Available Bids</h1>
          <p className="mt-2 text-sm text-slate-500">Open orders available for transporter bids are shown here.</p>
        </div>

        {loading && <div className="rounded-xl border border-blue-200 bg-blue-50 px-4 py-3 text-sm text-blue-700">Loading bids...</div>}
        {error && <div className="rounded-xl border border-red-200 bg-red-50 px-4 py-3 text-sm text-red-700">{error}</div>}
        {success && <div className="rounded-xl border border-emerald-200 bg-emerald-50 px-4 py-3 text-sm text-emerald-700">{success}</div>}

        {!loading && !error && locationSetupRequired && (
          <div className="rounded-xl border border-amber-200 bg-amber-50 px-5 py-4 text-sm text-amber-800">
            <i className="fas fa-location-dot mr-2" aria-hidden="true"></i>
            None of your active trucks has an operating location yet. Set each truck's current
            location and service radius in its configuration to see nearby orders.
          </div>
        )}

        {!loading && !error && orders.length === 0 && !locationSetupRequired && ordersOutOfRange > 0 && (
          <div className="rounded-xl border border-slate-200 bg-white px-5 py-10 text-center text-sm text-slate-500">
            {ordersOutOfRange} open order{ordersOutOfRange === 1 ? '' : 's'} match your trucks' cargo
            capability but the pickup is outside their service radius. Move a truck closer or widen
            its radius (up to 150 km) to bid.
          </div>
        )}

        {!loading && !error && orders.length === 0 && !locationSetupRequired && ordersOutOfRange === 0 && (
          <div className="rounded-xl border border-slate-200 bg-white px-5 py-10 text-center text-sm text-slate-500">
            No open bids near your trucks right now. Check back soon.
          </div>
        )}

        {!loading && !error && orders.length > 0 && (
          <div className="grid gap-4 xl:grid-cols-2">
            {orders.map((order) => {
              return (
                <article key={order.id} className="rounded-xl border border-slate-200 bg-white p-5 shadow-sm">
                  <div className="flex items-start justify-between gap-3">
                    <div>
                      <h2 className="text-lg font-bold text-slate-900">{order.pickup_city}{' -> '}{order.dropoff_city}</h2>
                      <p className="mt-1 text-sm text-slate-500">{order.pickup_date} at {order.pickup_time}</p>
                    </div>
                    <div className="flex flex-col items-end gap-1">
                      <span className="rounded-full bg-amber-50 px-3 py-1 text-xs font-semibold text-amber-700">{order.bid_count} bids</span>
                      {order.distance_to_pickup_km != null && (
                        <span className="rounded-full bg-emerald-50 px-3 py-1 text-xs font-semibold text-emerald-700">
                          <i className="fas fa-location-arrow mr-1" aria-hidden="true"></i>
                          {order.distance_to_pickup_km} km to pickup
                        </span>
                      )}
                    </div>
                  </div>
                  <div className="mt-4 grid gap-3 text-sm text-slate-600 sm:grid-cols-2">
                    <div><span className="font-semibold text-slate-800">Goods:</span> {order.goods_type}</div>
                    <div><span className="font-semibold text-slate-800">Weight:</span> {order.goods_weight_tons} tons</div>
                    <div><span className="font-semibold text-slate-800">Volume:</span> {order.goods_volume_cbm ? `${order.goods_volume_cbm} cbm` : 'Not shared'}</div>
                    <div><span className="font-semibold text-slate-800">Budget:</span> {order.estimated_budget ? formatMoney(order.estimated_budget) : 'Not shared'}</div>
                  </div>
                  <button type="button" onClick={() => openBidForm(order)} className="mt-4 inline-flex min-h-10 items-center justify-center rounded-lg bg-blue-600 px-4 py-2 text-sm font-semibold text-white hover:bg-blue-700">
                    <i className="fas fa-gavel mr-2" aria-hidden="true"></i>
                    Place Bid
                  </button>
                </article>
              )
            })}
          </div>
        )}

        {selectedOrder && (
          <div className="rounded-2xl border border-slate-200 bg-white p-6 shadow-sm">
            <div className="flex items-start justify-between gap-3">
              <div>
                <h2 className="text-xl font-bold text-slate-900">Place Bid for Order #{selectedOrder.id}</h2>
                <p className="mt-1 text-sm text-slate-500">{selectedOrder.pickup_city} to {selectedOrder.dropoff_city}</p>
              </div>
              <button type="button" onClick={() => setSelectedOrderId(null)} className="rounded-lg border border-slate-300 px-3 py-2 text-sm font-semibold text-slate-700 hover:bg-slate-50">
                Close
              </button>
            </div>

            <form className="mt-5 grid gap-4 md:grid-cols-2" onSubmit={submitBid}>
              <label className="grid gap-2 text-sm font-medium text-slate-700">
                Truck
                <select className="rounded-lg border border-slate-300 px-3 py-2.5" name="truck_id" value={form.truck_id} onChange={updateForm} required>
                  <option value="">Select active truck</option>
                  {activeTrucks.map((truck) => (
                    <option key={truck.id} value={truck.id}>{truck.truck_number} - {truck.truck_type}</option>
                  ))}
                </select>
              </label>
              <label className="grid gap-2 text-sm font-medium text-slate-700">
                Bid price
                <input className="rounded-lg border border-slate-300 px-3 py-2.5" type="number" min="0.01" step="0.01" name="bid_price" value={form.bid_price} onChange={updateForm} required />
              </label>
              <label className="grid gap-2 text-sm font-medium text-slate-700 md:col-span-2">
                Message
                <textarea className="min-h-24 rounded-lg border border-slate-300 px-3 py-2.5" name="message" value={form.message} onChange={updateForm} placeholder="Share timing, service notes, or capacity details." />
              </label>
              <div className="md:col-span-2">
                <button type="submit" disabled={submitting || activeTrucks.length === 0} className="inline-flex min-h-10 items-center justify-center rounded-lg bg-blue-600 px-4 py-2 text-sm font-semibold text-white hover:bg-blue-700 disabled:cursor-not-allowed disabled:opacity-60">
                  <i className={`fas ${submitting ? 'fa-spinner fa-spin' : 'fa-gavel'} mr-2`} aria-hidden="true"></i>
                  {submitting ? 'Submitting bid...' : 'Submit bid'}
                </button>
                {activeTrucks.length === 0 && (
                  <p className="mt-2 text-sm text-amber-700">You do not currently have an active truck available.</p>
                )}
              </div>
            </form>
          </div>
        )}
      </div>

  )
}

import { useEffect, useMemo, useState } from 'react'
import { Link } from 'react-router-dom'
import AgreementTripMap from '../../components/AgreementTripMap'
import { hasTruckPhoto, truckPhotoBackgroundStyle } from '../../lib/truckPhotos'
import { PrimaryButton, SecondaryButton, StateMessage, StatusBadge, apiGet, apiSend, formatMoney, formatNumber } from '../client/clientUtils'
import '../../styles/pages/my-agreements.css'

function getPosition() {
  return new Promise((resolve, reject) => {
    if (!navigator.geolocation) {
      reject(new Error('Browser geolocation is not available.'))
      return
    }
    navigator.geolocation.getCurrentPosition(
      (position) => resolve(position.coords),
      () => reject(new Error('Unable to read GPS coordinates.')),
      { enableHighAccuracy: true, timeout: 15000 },
    )
  })
}

export default function MyAgreements() {
  const [agreements, setAgreements] = useState([])
  const [trips, setTrips] = useState({})
  const [descriptions, setDescriptions] = useState({})
  const [loading, setLoading] = useState(true)
  const [working, setWorking] = useState('')
  const [error, setError] = useState('')
  const [notice, setNotice] = useState('')

  async function loadData() {
    setLoading(true)
    setError('')
    try {
      const json = await apiGet('/api/agreements/my')
      setAgreements(json.agreements || [])
      const tripEntries = await Promise.all((json.agreements || []).map(async (agreement) => {
        try {
          const tripJson = await apiGet(`/api/agreements/${agreement.id}/trips`)
          return [agreement.id, tripJson.trips || []]
        } catch (_) {
          return [agreement.id, []]
        }
      }))
      setTrips(Object.fromEntries(tripEntries))
    } catch (loadError) {
      setError(loadError.message || 'Unable to load agreements.')
    } finally {
      setLoading(false)
    }
  }

  useEffect(() => {
    loadData()
  }, [])

  const activeTripByTruck = useMemo(() => {
    const map = {}
    Object.values(trips).flat().forEach((trip) => {
      if (trip.status === 'in_progress') map[`${trip.agreement_id}:${trip.truck_id}`] = trip
    })
    return map
  }, [trips])

  async function startTrip(agreement, truck) {
    const key = `${agreement.id}:${truck.truck_id}`
    const pickup_description = (descriptions[key] || '').trim()
    if (!pickup_description) {
      setError('Trip description is required.')
      return
    }
    setWorking(`start:${key}`)
    setError('')
    setNotice('')
    try {
      const coords = await getPosition()
      await apiSend(`/api/agreements/${agreement.id}/trips`, {
        truck_id: truck.truck_id,
        pickup_description,
        gps_start_lat: coords.latitude,
        gps_start_lng: coords.longitude,
      })
      setNotice(`${truck.truck_number} - TRIP IN PROGRESS: ${pickup_description}. Tap End Trip when truck returns to base.`)
      await loadData()
    } catch (startError) {
      setError(startError.message || 'Unable to start trip.')
    } finally {
      setWorking('')
    }
  }

  async function endTrip(agreement, truck, trip) {
    const key = `${agreement.id}:${truck.truck_id}`
    setWorking(`end:${key}`)
    setError('')
    setNotice('')
    try {
      const coords = await getPosition()
      const json = await apiSend(`/api/agreements/${agreement.id}/trips/${trip.id}/end`, {
        gps_end_lat: coords.latitude,
        gps_end_lng: coords.longitude,
      }, 'PUT')
      const earned = Number(json.distance_km || 0) * Number(truck.per_km_rate || 0)
      const src = json.distance_source ? ` (${json.distance_source})` : ''
      setNotice(`Trip complete! Distance: ${formatNumber(json.distance_km)} km${src} | Earned: ${formatMoney(earned)}`)
      await loadData()
    } catch (endError) {
      setError(endError.message || 'Unable to end trip.')
    } finally {
      setWorking('')
    }
  }

  return (
    <div className="myagreements-page">
      <div className="myagreements-page-title">
        <div>
          <h1>My Agreements</h1>
          <p>Manage trips and monthly earnings for assigned agreement trucks.</p>
        </div>
        <Link to="/transporter/agreement-bids" className="myagreements-primary-btn">
          <i className="fas fa-file-signature" aria-hidden="true"></i>
            Agreement Bids
        </Link>
      </div>

      {loading && <StateMessage type="loading">Loading agreements...</StateMessage>}
      {error && <StateMessage type="error">{error}</StateMessage>}
      {notice && <StateMessage type="success">{notice}</StateMessage>}
      {!loading && !error && agreements.length === 0 && (
        <div className="myagreements-empty-state">
          <i className="fas fa-file-contract" aria-hidden="true"></i>
          <p>No active transporter agreements yet.</p>
          <Link to="/transporter/agreement-bids">Browse Agreement Bids</Link>
        </div>
      )}

      <div className="myagreements-grid">
        {agreements.map((agreement) => (
          <article key={agreement.id} className="myagreements-card">
            <div className="myagreements-card-header">
              <div>
                <h2>Agreement #{agreement.id} with {agreement.client_name}</h2>
                <p>{agreement.cargo_type} | {agreement.duration_months} months</p>
              </div>
              <StatusBadge status={agreement.status} />
            </div>
            <div className="myagreements-summary">
              This month: {formatNumber(agreement.current_month_km)} km | Projected payment {formatMoney(agreement.current_month_earnings)}
            </div>
            <div className="myagreements-truck-list">
              {(agreement.trucks || []).map((truck) => {
                const key = `${agreement.id}:${truck.truck_id}`
                const activeTrip = activeTripByTruck[key]
                return (
                  <div
                    key={truck.id}
                    className={`myagreements-truck-card${hasTruckPhoto(truck) ? ' myagreements-truck-card--has-photo' : ''}`}
                    style={truckPhotoBackgroundStyle(truck)}
                  >
                    {activeTrip && (
                      <div className="myagreements-trip-alert">
                        {truck.truck_number} - TRIP IN PROGRESS: {activeTrip.pickup_description}
                      </div>
                    )}
                    {activeTrip && (
                      <div className="myagreements-map-wrap">
                        <AgreementTripMap tripId={activeTrip.id} isActive={true} />
                      </div>
                    )}
                    <div className="myagreements-truck-row">
                      <div className="myagreements-truck-info">
                        <div>{truck.truck_number} - {truck.truck_type_name}</div>
                        <div>{formatMoney(truck.per_km_rate)} per km | Minimum {formatMoney(truck.minimum_monthly_guarantee)}</div>
                      </div>
                      {!activeTrip ? (
                        <div className="myagreements-trip-actions">
                          <input className="myagreements-trip-input" placeholder="Trip description" value={descriptions[key] || ''} onChange={(event) => setDescriptions((current) => ({ ...current, [key]: event.target.value }))} />
                          <PrimaryButton type="button" className="myagreements-action-btn" onClick={() => startTrip(agreement, truck)} disabled={working === `start:${key}`}>
                            <i className={`fas ${working === `start:${key}` ? 'fa-spinner fa-spin' : 'fa-play'}`} aria-hidden="true"></i>
                            Trip Start
                          </PrimaryButton>
                        </div>
                      ) : (
                        <SecondaryButton type="button" className="myagreements-action-btn" onClick={() => endTrip(agreement, truck, activeTrip)} disabled={working === `end:${key}`}>
                          <i className={`fas ${working === `end:${key}` ? 'fa-spinner fa-spin' : 'fa-stop'}`} aria-hidden="true"></i>
                          End Trip
                        </SecondaryButton>
                      )}
                    </div>
                  </div>
                )
              })}
            </div>
          </article>
        ))}
      </div>
    </div>
  )
}

